-- Translations of the shared study content (lessons, quizzes, cards) into
-- Russian and Kazakh. The original English stays in the row; each language
-- sits beside it in `i18n`, and a missing field falls back to the original.

alter table public.lessons add column if not exists i18n jsonb not null default '{}'::jsonb;
alter table public.lesson_blocks add column if not exists i18n jsonb not null default '{}'::jsonb;
alter table public.quiz_questions add column if not exists i18n jsonb not null default '{}'::jsonb;
alter table public.flashcards add column if not exists i18n jsonb not null default '{}'::jsonb;

update public.lessons set i18n = $j${"ru": {"title": "Корни и коэффициенты", "summary": "Многочлен и его корни — один и тот же объект, записанный двумя способами. Формулы Виета переводят одно в другое, и бо́льшая часть олимпиадной алгебры — это умение понять, в какую сторону их читать."}, "kk": {"title": "Түбірлер мен коэффициенттер", "summary": "Көпмүше мен оның түбірлері — екі түрлі жазылған бір нысан. Виет формулалары бірін екіншісіне аударады, ал олимпиадалық алгебраның басым бөлігі — оларды қай бағытта оқу керегін білу."}}$j$::jsonb where id = 'algebra-roots-and-coefficients';
update public.lessons set i18n = $j${"ru": {"title": "Считать, не перебирая", "summary": "Четыре приёма, которыми решается большинство задач на подсчёт: перемножить независимые выборы, разделить на порядки, которые не важны, посчитать дополнение и вернуть то, что вычли дважды."}, "kk": {"title": "Тізбей санамай есептеу", "summary": "Есептеу есептерінің көбін шешетін төрт тәсіл: тәуелсіз таңдауларды көбейту, маңызы жоқ реттерге бөлу, толықтауышты санау және екі рет алынғанды қайта қосу."}}$j$::jsonb where id = 'combinatorics-counting';
update public.lessons set i18n = $j${"ru": {"title": "Сопротивление и что на самом деле его меняет", "summary": "Откуда берётся R = rho L / A, почему растянутая проволока теряет проводимость быстрее, чем кажется, и как складываются резисторы."}, "kk": {"title": "Кедергі және оны шын мәнінде не өзгертеді", "summary": "R = rho L / A қайдан шығады, созылған сымның кедергісі неге күткеннен тез өседі және резисторлар қалай қосылады."}}$j$::jsonb where id = 'electrodynamics-resistance';
update public.lessons set i18n = $j${"ru": {"title": "Связанные тела и качение", "summary": "Две идеи, на которых держится бо́льшая часть олимпиадной механики: тела, связанные нитью, движутся с одним ускорением, а у тела, катящегося без проскальзывания, вращение жёстко связано с движением."}, "kk": {"title": "Байланысқан денелер және домалау", "summary": "Олимпиадалық механиканың көбін көтеретін екі идея: жіппен байланған денелер бір үдеумен қозғалады, ал сырғанаусыз домалайтын дененің айналуы қозғалысымен қатаң байланысты."}}$j$::jsonb where id = 'mechanics-connected-bodies';
update public.lessons set i18n = $j${"ru": {"title": "Делимость, алгоритм Евклида и порядки", "summary": "Почему НОД ищут через остатки, а не через разложение на множители, и как переход от числа к показателю степени решает вопросы об огромных степенях."}, "kk": {"title": "Бөлінгіштік, Евклид алгоритмі және реттер", "summary": "ЕҮОБ-ты неге көбейткіштерге жіктеу арқылы емес, қалдықтар арқылы табады және санның орнына дәреже көрсеткішімен жұмыс істеу орасан зор дәрежелер туралы сұрақтарды қалай шешеді."}}$j$::jsonb where id = 'number-theory-divisibility';
update public.lessons set i18n = $j${"ru": {"title": "Первое начало и площадь под кривой pV", "summary": "Учёт теплоты и работы: что означают знаки, как считывать работу с pV-диаграммы и отношением чего на самом деле является КПД."}, "kk": {"title": "Бірінші заң және pV қисығы астындағы аудан", "summary": "Жылу мен жұмыстың есебі: таңбалар нені білдіреді, жұмысты pV-диаграммадан қалай оқу керек және ПӘК шын мәнінде ненің қатынасы."}}$j$::jsonb where id = 'thermodynamics-first-law';

update public.lesson_blocks set i18n = $j${"ru": {"heading": "Многочлен — это его корни", "body": "Любой многочлен степени n раскладывается над комплексными числами на n линейных множителей:\n\n    a x^2 + b x + c = a (x - r)(x - s)\n\nРаскройте скобки справа и сравните. Коэффициенты — не случайные числа, оказавшиеся на своих местах: они составлены из корней:\n\n    r + s = -b/a        r s = c/a\n\nЭто формулы Виета. Для кубического многочлена a x^3 + b x^2 + c x + d с корнями r, s, t:\n\n    r+s+t = -b/a        rs+rt+st = c/a        rst = -d/a\n\nЗакономерность продолжается: суммы произведений корней по одному, по два, по три, с чередующимся знаком."}, "kk": {"heading": "Көпмүше — оның түбірлері", "body": "n-дәрежелі кез келген көпмүше комплекс сандар үстінде n сызықтық көбейткішке жіктеледі:\n\n    a x^2 + b x + c = a (x - r)(x - s)\n\nОң жақтағы жақшаларды ашып, салыстырыңыз. Коэффициенттер өз орнына кездейсоқ түскен сандар емес — олар түбірлерден құралған:\n\n    r + s = -b/a        r s = c/a\n\nБұл — Виет формулалары. r, s, t түбірлері бар a x^3 + b x^2 + c x + d кубтық көпмүшесі үшін:\n\n    r+s+t = -b/a        rs+rt+st = c/a        rst = -d/a\n\nЗаңдылық жалғаса береді: түбірлердің бір-бірден, екі-екіден, үш-үштен алынған көбейтінділерінің қосындылары, таңбасы кезектесіп отырады."}}$j$::jsonb where lesson_id = 'algebra-roots-and-coefficients' and position = 0;
update public.lesson_blocks set i18n = $j${"ru": {"heading": "Зачем это нужно", "body": "Потому что очень многие вопросы спрашивают о корнях, не требуя самих корней.\n\n«Найдите сумму квадратов корней» — кажется, что нужны оба корня. Это не так:\n\n    r^2 + s^2 = (r+s)^2 - 2rs\n\nи обе части уже видны в коэффициентах. Тот же приём работает для 1/r + 1/s = (r+s)/(rs) и для r^3 + s^3 = (r+s)^3 - 3rs(r+s).\n\nГлавный навык: переписать то, что спрашивают, через симметрические выражения r+s и rs, а затем взять их из коэффициентов. Решать квадратное уравнение — медленный путь, а на олимпиаде часто и невозможный.\n\nРаботает и в обратную сторону. Зная нужные сумму и произведение, можно сразу записать квадратное уравнение с такими корнями: x^2 - (сумма)x + (произведение) = 0."}, "kk": {"heading": "Бұл не үшін керек", "body": "Өйткені көптеген сұрақтар түбірлердің өзін талап етпей, түбірлер туралы сұрайды.\n\n«Түбірлер квадраттарының қосындысын табыңыз» — екі түбір де керек сияқты. Олай емес:\n\n    r^2 + s^2 = (r+s)^2 - 2rs\n\nал екі бөлігі де коэффициенттерде көрініп тұр. Дәл осы тәсіл 1/r + 1/s = (r+s)/(rs) және r^3 + s^3 = (r+s)^3 - 3rs(r+s) үшін де жұмыс істейді.\n\nМеңгеретін дағды: сұралғанды r+s және rs симметриялық өрнектері арқылы қайта жазып, оларды коэффициенттерден алу. Квадрат теңдеуді шешу — баяу жол, ал олимпиадада көбіне мүмкін емес.\n\nКері бағытта да жұмыс істейді. Қажетті қосынды мен көбейтінді белгілі болса, сондай түбірлері бар квадрат теңдеуді бірден жазуға болады: x^2 - (қосынды)x + (көбейтінді) = 0."}}$j$::jsonb where lesson_id = 'algebra-roots-and-coefficients' and position = 1;
update public.lesson_blocks set i18n = $j${"ru": {"heading": "Ни разу не найдя корень", "body": "Пусть r и s — корни уравнения 2x^2 - 7x + 3 = 0. Найдите r^2 + s^2.\n\n    r + s = 7/2        r s = 3/2\n    r^2 + s^2 = (r+s)^2 - 2rs = 49/4 - 3 = 37/4\n\nМожно проверить: корни равны 3 и 1/2, и 9 + 1/4 = 37/4. Но в вычислении они не понадобились, а для кубического уравнения с некрасивыми корнями проверять было бы нечем."}, "kk": {"heading": "Түбірді бір рет те таппай", "body": "r және s — 2x^2 - 7x + 3 = 0 теңдеуінің түбірлері болсын. r^2 + s^2 табыңыз.\n\n    r + s = 7/2        r s = 3/2\n    r^2 + s^2 = (r+s)^2 - 2rs = 49/4 - 3 = 37/4\n\nТексеруге болады: түбірлер 3 және 1/2, ал 9 + 1/4 = 37/4. Бірақ есептеуде олар қажет болмады, ал түбірлері әдемі емес кубтық теңдеу үшін тексеретін ештеңе болмас еді."}}$j$::jsonb where lesson_id = 'algebra-roots-and-coefficients' and position = 2;
update public.lesson_blocks set i18n = $j${"ru": {"heading": "Стоит запомнить", "items": ["Квадратное уравнение: r+s = -b/a и rs = c/a.", "Кубическое: сумма = -b/a, сумма попарных произведений = c/a, произведение = -d/a.", "r^2+s^2 = (r+s)^2 - 2rs. Выучите это преобразование: оно встречается постоянно.", "Если сумма S и произведение P известны, квадратное уравнение с такими корнями: x^2 - Sx + P = 0.", "Дискриминант b^2-4ac: положителен — два действительных корня; равен нулю — один кратный; отрицателен — пара комплексно сопряжённых.", "Невещественные корни многочлена с действительными коэффициентами идут комплексно сопряжёнными парами. Иррациональные корни образуют пары a ± √b только при рациональных коэффициентах: у x - √2 коэффициенты действительные, а корень один — √2."]}, "kk": {"heading": "Есте сақтаған жөн", "items": ["Квадрат теңдеу: r+s = -b/a және rs = c/a.", "Кубтық: қосынды = -b/a, жұп көбейтінділердің қосындысы = c/a, көбейтінді = -d/a.", "r^2+s^2 = (r+s)^2 - 2rs. Бұл түрлендіруді жаттап алыңыз: ол үнемі кездеседі.", "S қосындысы мен P көбейтіндісі белгілі болса, сондай түбірлері бар квадрат теңдеу: x^2 - Sx + P = 0.", "Дискриминант b^2-4ac: оң — екі нақты түбір; нөл — бір еселі түбір; теріс — түйіндес комплекс жұп.", "Нақты коэффициентті көпмүшенің нақты емес түбірлері түйіндес комплекс жұптармен келеді. Иррационал түбірлер a ± √b жұптарын тек рационал коэффициенттерде құрайды: x - √2 коэффициенттері нақты, ал түбірі біреу — √2."]}}$j$::jsonb where lesson_id = 'algebra-roots-and-coefficients' and position = 3;
update public.lesson_blocks set i18n = $j${"ru": {"heading": "Множители и остатки", "body": "При делении многочлена p(x) на (x - k) остаток равен в точности p(k). Это теорема Безу, а её полезная половина — теорема о множителе: (x - k) делит p(x) ровно тогда, когда p(k) = 0.\n\nЗначит, проверка кандидата в корни — это подстановка, а не деление. А если коэффициенты целые, теорема о рациональных корнях сужает кандидатов до короткого списка: у любого рационального корня p/q в несократимой записи p делит свободный член, а q — старший коэффициент.\n\nВместе они превращают «разложите этот кубический многочлен» из перебора в несколько подстановок."}, "kk": {"heading": "Көбейткіштер мен қалдықтар", "body": "p(x) көпмүшесін (x - k)-ға бөлгенде қалдық дәл p(k)-ға тең. Бұл — Безу теоремасы, ал оның пайдалы жартысы — көбейткіш туралы теорема: (x - k) p(x)-ті p(k) = 0 болғанда ғана бөледі.\n\nЯғни түбірге үміткерді тексеру — бөлу емес, қою. Ал коэффициенттер бүтін болса, рационал түбірлер туралы теорема үміткерлерді қысқа тізімге дейін тарылтады: қысқартылмайтын p/q рационал түбірінде p бос мүшені, q жоғарғы коэффициентті бөледі.\n\nБірге олар «осы кубтық көпмүшені жіктеңіз» дегенді іздеуден бірнеше қоюға айналдырады."}}$j$::jsonb where lesson_id = 'algebra-roots-and-coefficients' and position = 4;
update public.lesson_blocks set i18n = $j${"ru": {"heading": "Стоит запомнить", "items": ["Остаток от деления p(x) на (x-k) равен p(k).", "(x-k) — множитель ровно тогда, когда p(k) = 0.", "Рациональный корень p/q: p делит свободный член, q делит старший коэффициент.", "Степень произведения равна сумме степеней.", "Многочлен степени n имеет над комплексными числами ровно n корней с учётом кратности."]}, "kk": {"heading": "Есте сақтаған жөн", "items": ["p(x)-ті (x-k)-ға бөлгендегі қалдық p(k)-ға тең.", "(x-k) p(k) = 0 болғанда ғана көбейткіш болады.", "Рационал түбір p/q: p бос мүшені, q жоғарғы коэффициентті бөледі.", "Көбейтіндінің дәрежесі дәрежелердің қосындысына тең.", "n-дәрежелі көпмүшенің комплекс сандар үстінде еселігін ескергенде дәл n түбірі бар."]}}$j$::jsonb where lesson_id = 'algebra-roots-and-coefficients' and position = 5;
update public.lesson_blocks set i18n = $j${"ru": {"heading": "Умножать или складывать", "body": "Всё остальное держится на двух правилах.\n\nЕсли выбор делается по этапам и этапы независимы, перемножайте: три рубашки и четыре галстука дают двенадцать вариантов. Если случаи — взаимоисключающие альтернативы, складывайте: комиссию, состоящую либо только из первокурсников, либо только из второкурсников, считают как одно количество плюс другое.\n\nБольшинство ошибок на этом уровне — не арифметика. Это умножение там, где этапы мешают друг другу, или сложение там, где случаи пересекаются."}, "kk": {"heading": "Көбейту немесе қосу", "body": "Қалғанының бәрі екі ережеге сүйенеді.\n\nЕгер таңдау кезеңдермен жасалса және кезеңдер тәуелсіз болса, көбейтіңіз: үш көйлек пен төрт галстук он екі нұсқа береді. Егер жағдайлар бір мезгілде орындала алмайтын балама болса, қосыңыз: тек бірінші курстардан немесе тек екінші курстардан тұратын комиссия бір санға екіншісін қосу арқылы есептеледі.\n\nБұл деңгейдегі қателердің көбі арифметика емес. Олар — кезеңдер бір-біріне кедергі келтіретін жерде көбейту немесе жағдайлар қиылысатын жерде қосу."}}$j$::jsonb where lesson_id = 'combinatorics-counting' and position = 0;
update public.lesson_blocks set i18n = $j${"ru": {"heading": "Порядок и деление на него", "body": "Расставить в ряд k предметов из n — это произведение: n вариантов, затем n-1 и так далее, всего k множителей. Это число размещений P(n,k) = n! / (n-k)!.\n\nЕсли порядок не важен, каждая группа посчитана столько раз, сколькими способами её можно упорядочить, — k! раз. Разделив на это, получаем биномиальный коэффициент:\n\n    C(n,k) = n! / (k! (n-k)!)\n\nЭто деление — вся разница между ними, а понять, что именно нужно в задаче, — обычно и есть вся трудность. «Сколькими способами выстроить» — размещение; «сколькими способами выбрать» — сочетание.\n\nСимметрия C(n,k) = C(n,n-k) говорит одно и то же дважды: выбрать, какие k взять, — то же, что выбрать, какие n-k оставить."}, "kk": {"heading": "Рет және оған бөлу", "body": "n заттан k-сын қатарға қою — көбейтінді: n нұсқа, содан кейін n-1 және т.с.с., барлығы k көбейткіш. Бұл — орналастырулар саны P(n,k) = n! / (n-k)!.\n\nЕгер рет маңызды болмаса, әр топ оны реттеу тәсілдерінің санынша — k! рет саналған. Оған бөлсек, биномдық коэффициент шығады:\n\n    C(n,k) = n! / (k! (n-k)!)\n\nОсы бөлу — олардың арасындағы бүкіл айырма, ал есепте қайсысы керегін анықтау — әдетте бүкіл қиындық. «Қанша тәсілмен қатарға тұрғызуға болады» — орналастыру; «қанша тәсілмен таңдауға болады» — теру.\n\nC(n,k) = C(n,n-k) симметриясы бір нәрсені екі рет айтады: қай k-ны алуды таңдау — қай n-k-ны қалдыруды таңдау."}}$j$::jsonb where lesson_id = 'combinatorics-counting' and position = 1;
update public.lesson_blocks set i18n = $j${"ru": {"heading": "Комиссия и пьедестал", "body": "Восемь кандидатов.\n\nВыбрать трёх в комиссию, где ни у кого нет должности:\n    C(8,3) = 8*7*6 / (3*2*1) = 56\n\nВыбрать трёх на первое, второе и третье места, где места различаются:\n    P(8,3) = 8*7*6 = 336\n\nВторое ровно в 3! = 6 раз больше первого, потому что каждую тройку можно расставить на пьедестале шестью способами."}, "kk": {"heading": "Комиссия және тұғыр", "body": "Сегіз үміткер.\n\nЕшкімнің лауазымы жоқ комиссияға үшеуін таңдау:\n    C(8,3) = 8*7*6 / (3*2*1) = 56\n\nОрындары әртүрлі бірінші, екінші және үшінші орындарға үшеуін таңдау:\n    P(8,3) = 8*7*6 = 336\n\nЕкіншісі біріншісінен дәл 3! = 6 есе көп, өйткені әр үштікті тұғырға алты тәсілмен орналастыруға болады."}}$j$::jsonb where lesson_id = 'combinatorics-counting' and position = 2;
update public.lesson_blocks set i18n = $j${"ru": {"heading": "Стоит запомнить", "items": ["Независимые этапы перемножаются; взаимоисключающие случаи складываются.", "Порядок важен: P(n,k) = n!/(n-k)!. Не важен: C(n,k) = n!/(k!(n-k)!).", "C(n,k) = C(n,n-k) — выбрать, что взять, значит выбрать, что оставить.", "C(n,0) = C(n,n) = 1, а сумма строки C(n,k) равна 2^n.", "0! = 1 — именно поэтому формулы работают на краях."]}, "kk": {"heading": "Есте сақтаған жөн", "items": ["Тәуелсіз кезеңдер көбейтіледі; бір-бірін жоққа шығаратын жағдайлар қосылады.", "Рет маңызды: P(n,k) = n!/(n-k)!. Маңызды емес: C(n,k) = n!/(k!(n-k)!).", "C(n,k) = C(n,n-k) — нені алуды таңдау, нені қалдыруды таңдау деген сөз.", "C(n,0) = C(n,n) = 1, ал C(n,k) жолының қосындысы 2^n.", "0! = 1 — формулалардың шеттерде жұмыс істейтіні сондықтан."]}}$j$::jsonb where lesson_id = 'combinatorics-counting' and position = 3;
update public.lesson_blocks set i18n = $j${"ru": {"heading": "Посчитайте противоположное", "body": "«Хотя бы один» почти всегда проще считать наоборот. Расстановок, где хотя бы одна цифра повторяется, столько же, сколько всех минус те, где повторов нет; раздач, где есть хотя бы один туз, — все раздачи минус раздачи без тузов.\n\nКогда складываемые случаи начинают пересекаться, учёт держит формула включений-исключений. Для двух множеств:\n\n    |A или B| = |A| + |B| - |A и B|\n\nОдин раз вычесть пересечение — значит исправить то, что при сложении двух количеств оно посчитано дважды. Для трёх множеств закономерность продолжается: прибавить одиночные, вычесть попарные, вернуть тройное."}, "kk": {"heading": "Қарсысын санаңыз", "body": "«Кемінде біреу» дегенді әрдайым дерлік керісінше санау оңай. Кемінде бір цифры қайталанатын орналастырулар — барлығы минус қайталанбайтындары; кемінде бір тұзы бар таратулар — барлық таратулар минус тұзсыздары.\n\nҚосылатын жағдайлар қиылыса бастағанда, есепті қосу-шегеру формуласы түзу ұстайды. Екі жиын үшін:\n\n    |A немесе B| = |A| + |B| - |A және B|\n\nҚиылысуды бір рет шегеру екі санды қосқанда оның екі рет саналғанын түзетеді. Үш жиын үшін заңдылық жалғасады: жалғыздарды қосу, жұптарды шегеру, үштікті қайта қосу."}}$j$::jsonb where lesson_id = 'combinatorics-counting' and position = 4;
update public.lesson_blocks set i18n = $j${"ru": {"heading": "Стоит запомнить", "items": ["«Хотя бы один» обычно значит: все минус ни одного.", "Два множества: |A или B| = |A| + |B| - |A и B|.", "Три множества: одиночные минус попарные плюс тройное.", "Принцип Дирихле: n+1 предмет в n ящиках — в каком-то ящике два. Сформулировать легко, заметить трудно.", "Шары и перегородки: k одинаковых предметов по n различным ящикам — C(k+n-1, n-1) способов."]}, "kk": {"heading": "Есте сақтаған жөн", "items": ["«Кемінде біреу» әдетте: барлығы минус біреуі де жоқ.", "Екі жиын: |A немесе B| = |A| + |B| - |A және B|.", "Үш жиын: жалғыздар минус жұптар плюс үштік.", "Дирихле принципі: n жәшікте n+1 зат — бір жәшікте екеуі бар. Айту оңай, байқау қиын.", "Шарлар мен бөгеттер: k бірдей затты n таңбаланған жәшікке — C(k+n-1, n-1) тәсіл."]}}$j$::jsonb where lesson_id = 'combinatorics-counting' and position = 5;
update public.lesson_blocks set i18n = $j${"ru": {"heading": "Сопротивление — это форма, умноженная на материал", "body": "Сопротивление определяется как R = V / I: какую разность потенциалов нужно приложить, чтобы прогнать заданный ток.\n\nДля однородного проводника оно аккуратно распадается на свойство вещества и свойство формы:\n\n    R = rho * L / A\n\nrho — удельное сопротивление, характеристика материала и его температуры. L и A — длина и площадь поперечного сечения. Для однородного провода больше ничего в геометрии не важно."}, "kk": {"heading": "Кедергі — материалға көбейтілген пішін", "body": "Кедергі R = V / I ретінде анықталады: берілген токты өткізу үшін қандай потенциалдар айырмасы керек.\n\nБіртекті өткізгіш үшін ол заттың қасиеті мен пішіннің қасиетіне таза бөлінеді:\n\n    R = rho * L / A\n\nrho — меншікті кедергі, материал мен оның температурасының сипаттамасы. L және A — ұзындық пен көлденең қима ауданы. Біртекті сым үшін геометрияда басқа ештеңе маңызды емес."}}$j$::jsonb where lesson_id = 'electrodynamics-resistance' and position = 0;
update public.lesson_blocks set i18n = $j${"ru": {"heading": "Почему длина и площадь входят именно так", "body": "Представьте носители заряда, которые дрейфуют через кристаллическую решётку и рассеиваются по пути. Удвойте длину — при том же поле носителю нужно пройти вдвое больше и пережить вдвое больше столкновений: тот же ток требует вдвое большего напряжения, значит R удваивается. Сопротивление пропорционально L.\n\nТеперь удвойте сечение. Путь не меняется, но параллельно идёт вдвое больше носителей, поэтому то же напряжение даёт вдвое больший ток. Сопротивление обратно пропорционально A.\n\nПоэтому в формуле стоит площадь, а не диаметр. Удвоение диаметра увеличивает площадь в четыре раза и уменьшает сопротивление в четыре раза — это самая частая ошибка в этой теме."}, "kk": {"heading": "Ұзындық пен аудан неге дәл осылай кіреді", "body": "Кристалдық тор арқылы дрейфтеп, жолда шашырайтын заряд тасымалдаушыларды елестетіңіз. Ұзындықты екі есе арттырсаңыз, сол өрісте тасымалдаушыға екі есе ұзақ жүріп, екі есе көп соқтығысуға төтеп беру керек: сол ток екі есе көп кернеуді талап етеді, демек R екі еселенеді. Кедергі L-ге пропорционал.\n\nЕнді қиманы екі есе арттырыңыз. Жол өзгермейді, бірақ қатар екі есе көп тасымалдаушы жүреді, сондықтан сол кернеу екі есе көп ток береді. Кедергі A-ға кері пропорционал.\n\nСондықтан формулада диаметр емес, аудан тұр. Диаметрді екі есе арттыру ауданды төрт есе үлкейтіп, кедергіні төрт есе азайтады — бұл тақырыптағы ең жиі қате."}}$j$::jsonb where lesson_id = 'electrodynamics-resistance' and position = 1;
update public.lesson_blocks set i18n = $j${"ru": {"heading": "Проволоку растянули вдвое", "body": "Проволоку вытягивают, пока она не станет вдвое длиннее. Материал тот же, металл не теряется, поэтому объём L * A прежний.\n\n    L -> 2L,  а так как L*A постоянно,  A -> A/2\n    R = rho L / A  ->  rho (2L) / (A/2) = 4 * rho L / A\n\nСопротивление выросло в четыре раза. Оба множителя действуют в одну сторону, поэтому ответ 4, а не 2: при растяжении провод одновременно становится длиннее и тоньше."}, "kk": {"heading": "Сымды екі есе созды", "body": "Сымды екі есе ұзын болғанша созады. Материал сол, металл жоғалмайды, сондықтан L * A көлемі бұрынғыдай.\n\n    L -> 2L,  ал L*A тұрақты болғандықтан,  A -> A/2\n    R = rho L / A  ->  rho (2L) / (A/2) = 4 * rho L / A\n\nКедергі төрт есе өсті. Екі көбейткіш те бір жаққа әсер етеді, сондықтан жауап 2 емес, 4: созғанда сым бір мезгілде ұзарып та, жіңішкеріп те кетеді."}}$j$::jsonb where lesson_id = 'electrodynamics-resistance' and position = 2;
update public.lesson_blocks set i18n = $j${"ru": {"heading": "Стоит запомнить", "items": ["R = rho L / A для однородного проводника.", "rho — свойство материала и его температуры, а не формы.", "Удвоили длину — R удвоилось. Удвоили диаметр — R уменьшилось в четыре раза.", "Растяжение в n раз при постоянном объёме умножает R на n^2.", "У металла rho растёт с температурой, у полупроводника — падает."]}, "kk": {"heading": "Есте сақтаған жөн", "items": ["Біртекті өткізгіш үшін R = rho L / A.", "rho — пішіннің емес, материал мен оның температурасының қасиеті.", "Ұзындықты екі еселедіңіз — R екі еселенеді. Диаметрді екі еселедіңіз — R төрт есе азаяды.", "Тұрақты көлемде n есе созу R-ді n^2-ге көбейтеді.", "Металда rho температурамен өседі, жартылай өткізгіште — азаяды."]}}$j$::jsonb where lesson_id = 'electrodynamics-resistance' and position = 3;
update public.lesson_blocks set i18n = $j${"ru": {"heading": "Последовательно и параллельно", "body": "При последовательном соединении через каждый резистор идёт один и тот же ток, а напряжения складываются, поэтому складываются сопротивления: R = R1 + R2 + ...\n\nПри параллельном на каждом резисторе одно и то же напряжение, а складываются токи, поэтому складываются проводимости: 1/R = 1/R1 + 1/R2 + ...\n\nДва следствия, которые стоит держать в голове: добавление чего угодно последовательно всегда увеличивает общее сопротивление, а параллельно — всегда уменьшает, даже ниже самого маленького резистора в группе."}, "kk": {"heading": "Тізбектей және параллель", "body": "Тізбектей қосқанда әр резистор арқылы бірдей ток өтеді, ал кернеулер қосылады, сондықтан кедергілер қосылады: R = R1 + R2 + ...\n\nПараллель қосқанда әр резисторда бірдей кернеу, ал токтар қосылады, сондықтан өткізгіштіктер қосылады: 1/R = 1/R1 + 1/R2 + ...\n\nЕсте ұстайтын екі салдар: тізбектей кез келген нәрсені қосу жалпы кедергіні әрдайым арттырады, ал параллель қосу әрдайым азайтады — тіпті топтағы ең кіші резистордан да төмен."}}$j$::jsonb where lesson_id = 'electrodynamics-resistance' and position = 4;
update public.lesson_blocks set i18n = $j${"ru": {"heading": "Стоит запомнить", "items": ["Последовательно: сопротивления складываются. Параллельно: складываются обратные величины.", "Два одинаковых резистора параллельно дают половину одного; n одинаковых — R/n.", "Параллельное соединение всегда меньше своего наименьшего элемента.", "Два резистора параллельно: R = R1 R2 / (R1 + R2). Только для двух.", "Мощность: P = V I = I^2 R = V^2 / R. Выбирайте форму с теми двумя величинами, которые известны."]}, "kk": {"heading": "Есте сақтаған жөн", "items": ["Тізбектей: кедергілер қосылады. Параллель: кері шамалар қосылады.", "Екі бірдей резистор параллель біреуінің жартысын береді; n бірдей — R/n.", "Параллель қосылыс әрдайым өзінің ең кіші мүшесінен кіші.", "Параллель екі резистор: R = R1 R2 / (R1 + R2). Тек екеуі үшін.", "Қуат: P = V I = I^2 R = V^2 / R. Белгілі екі шамасы бар түрін таңдаңыз."]}}$j$::jsonb where lesson_id = 'electrodynamics-resistance' and position = 5;
update public.lesson_blocks set i18n = $j${"ru": {"heading": "Одна нить — связанные ускорения", "body": "Нерастяжимая нить имеет постоянную длину, и в этом всё ограничение. Запишите длину через координаты тел, продифференцируйте дважды — и получите связь между их ускорениями.\n\nДля двух тел на концах одной нити — поперёк стола или через неподвижный блок — связь самая простая: если один конец сдвинулся на сантиметр, то и другой тоже, поэтому у тел одна скорость и один модуль ускорения. С подвижным блоком иначе: груз, подвешенный к блоку, который едет по нити, проходит вдвое меньше свободного конца, поэтому его ускорение вдвое меньше.\n\nВ любом случае нить превращает два неизвестных ускорения в одно. Выводите связь для конкретной установки, а не предполагайте, что ускорения равны."}, "kk": {"heading": "Бір жіп — байланысқан үдеулер", "body": "Созылмайтын жіптің ұзындығы тұрақты, бүкіл шектеу де осы. Ұзындықты денелердің координаталары арқылы жазып, екі рет дифференциалдаңыз — олардың үдеулері арасындағы байланысты аласыз.\n\nБір жіптің екі ұшындағы екі дене үшін — үстел бойымен немесе қозғалмайтын блок арқылы — байланыс ең қарапайым: бір ұшы бір сантиметрге жылжыса, екіншісі де жылжиды, сондықтан денелердің жылдамдығы бір және үдеу модулі бір. Жылжымалы блокпен басқаша: жіп бойымен жүретін блокқа ілінген жүк бос ұшынан екі есе аз жол жүреді, сондықтан оның үдеуі екі есе аз.\n\nҚалай болғанда да жіп екі белгісіз үдеуді біреуге айналдырады. Үдеулерді тең деп болжамай, нақты қондырғы үшін байланысты шығарыңыз."}}$j$::jsonb where lesson_id = 'mechanics-connected-bodies' and position = 0;
update public.lesson_blocks set i18n = $j${"ru": {"heading": "Почему сложение уравнений убирает натяжение", "body": "Запишите второй закон Ньютона для каждого тела отдельно — вдоль направления, в котором это тело реально движется. Нить входит в оба уравнения: одно тело она тянет вперёд, другое — назад. Для лёгкой нити и блока без трения натяжение одинаково по всей нити, поэтому эти две силы равны по модулю. Это не пара сил по третьему закону: каждая из них — действие нити на тело, а её пара — тело, тянущее нить обратно.\n\nСложите уравнения — натяжение сократится, и останется одно уравнение для общего ускорения. Решите его, а затем подставьте в любое из исходных уравнений, чтобы найти только что исключённое натяжение.\n\nПорядок важен: сумма даёт движение системы, а внутреннюю силу может дать только уравнение для одного тела."}, "kk": {"heading": "Теңдеулерді қосу неге керілуді жояды", "body": "Ньютонның екінші заңын әр денеге бөлек — сол дене шын мәнінде қозғалатын бағыт бойымен жазыңыз. Жіп екі теңдеуге де кіреді: бір денені алға, екіншісін артқа тартады. Жеңіл жіп пен үйкеліссіз блок үшін керілу жіптің бойында бірдей, сондықтан бұл екі күштің модулі тең. Бұл үшінші заң бойынша жұп емес: әрқайсысы — жіптің денеге әсері, ал оның жұбы — жіпті кері тартатын дене.\n\nТеңдеулерді қосыңыз — керілу қысқарады да, ортақ үдеу үшін бір теңдеу қалады. Оны шешіп, жаңа ғана жойылған керілуді табу үшін бастапқы теңдеулердің кез келгеніне қойыңыз.\n\nРет маңызды: қосынды жүйенің қозғалысын береді, ал ішкі күшті тек бір дененің теңдеуі бере алады."}}$j$::jsonb where lesson_id = 'mechanics-connected-bodies' and position = 1;
update public.lesson_blocks set i18n = $j${"ru": {"heading": "Два бруска тянут по столу", "body": "Бруски массой 4,0 кг и 2,0 кг связаны лёгкой нитью и лежат на гладком столе. Горизонтальная сила 12 Н тянет брусок 4,0 кг, а тот тащит за собой брусок 2,0 кг.\n\nСистема:        F = (m1 + m2) a        ->   a = 12 / 6,0 = 2,0 м/с^2\nЗадний брусок:  T = m2 * a             ->   T = 2,0 * 2,0 = 4,0 Н\nПроверка переднего: F - T = 12 - 4,0 = 8,0 Н,  и m1 * a = 4,0 * 2,0 = 8,0 Н.  Сходится.\n\nОбратите внимание: натяжение не 12 Н и не 6 Н. Оно ровно такое, какое нужно, чтобы разогнать то, что сзади."}, "kk": {"heading": "Үстел бойымен тартылған екі білеуше", "body": "4,0 кг және 2,0 кг білеушелер жеңіл жіппен байланған және тегіс үстелде жатыр. 12 Н горизонталь күш 4,0 кг білеушені тартып, артындағы 2,0 кг білеушені сүйрейді.\n\nЖүйе:            F = (m1 + m2) a        ->   a = 12 / 6,0 = 2,0 м/с^2\nАртқы білеуше:   T = m2 * a             ->   T = 2,0 * 2,0 = 4,0 Н\nАлдыңғысын тексеру: F - T = 12 - 4,0 = 8,0 Н,  және m1 * a = 4,0 * 2,0 = 8,0 Н.  Сәйкес.\n\nНазар аударыңыз: керілу 12 Н де, 6 Н да емес. Ол артындағыны үдету үшін қажет күшке дәл тең."}}$j$::jsonb where lesson_id = 'mechanics-connected-bodies' and position = 2;
update public.lesson_blocks set i18n = $j${"ru": {"heading": "Стоит запомнить", "items": ["Нерастяжимая нить задаёт связь между ускорениями. Через неподвижный блок или прямо по столу они равны; с подвижным блоком — нет, связь выводится из длины нити.", "Одна схема сил на каждое тело. Схема вокруг обоих тел прячет силу между ними.", "Положительное направление берите вдоль движения каждого тела — тогда знаки расставятся сами.", "Сложите уравнения, чтобы найти движение, и подставьте обратно в одно из них, чтобы найти внутреннюю силу.", "У невесомой нити на невесомом блоке без трения натяжение одинаково по всей длине."]}, "kk": {"heading": "Есте сақтаған жөн", "items": ["Созылмайтын жіп үдеулер арасындағы байланысты белгілейді. Қозғалмайтын блок арқылы немесе үстел бойымен тура олар тең; жылжымалы блокпен — тең емес, байланысты жіптің ұзындығынан шығарыңыз.", "Әр денеге бір күштер сызбасы. Екі денені қоршаған сызба олардың арасындағы күшті жасырады.", "Оң бағытты әр дененің өз қозғалысы бойымен алыңыз — сонда таңбалар өздігінен дұрыс түседі.", "Қозғалысты табу үшін теңдеулерді қосыңыз, ішкі күшті табу үшін біреуіне қайта қойыңыз.", "Салмақсыз үйкеліссіз блок арқылы өткен салмақсыз жіптің керілуі бүкіл бойында бірдей."]}}$j$::jsonb where lesson_id = 'mechanics-connected-bodies' and position = 3;
update public.lesson_blocks set i18n = $j${"ru": {"heading": "Качение без проскальзывания", "body": "Колесо, катящееся без проскальзывания, касается земли в точке, которая в этот момент неподвижна. Точка касания — мгновенная ось; центр движется вперёд со скоростью v, а тело вращается с угловой скоростью omega.\n\nОтсюда две связи между движением и вращением: v = omega * R и a = alpha * R. Именно они позволяют одной неизвестной работать за две."}, "kk": {"heading": "Сырғанаусыз домалау", "body": "Сырғанаусыз домалайтын дөңгелек жерге сол сәтте мүлде қозғалмайтын нүктеде тиеді. Жанасу нүктесі — лездік ось; центр алға v жылдамдықпен қозғалады, ал дене omega бұрыштық жылдамдықпен айналады.\n\nБұдан қозғалыс пен айналу арасындағы екі байланыс шығады: v = omega * R және a = alpha * R. Дәл осылар бір белгісізге екеуінің жұмысын атқаруға мүмкіндік береді."}}$j$::jsonb where lesson_id = 'mechanics-connected-bodies' and position = 4;
update public.lesson_blocks set i18n = $j${"ru": {"heading": "Зачем нужно трение", "body": "Что-то должно раскручивать тело, а сила тяжести, приложенная к центру, не создаёт момента относительно центра. Это делает сила трения покоя в точке касания: только у неё есть плечо, поэтому она и задаёт угловое ускорение.\n\nПоскольку точка касания мгновенно покоится, сила трения действует без перемещения и потому не совершает работы. Энергия сохраняется, но делится: часть идёт на движение центра, часть на вращение, а пропорцию определяет момент инерции.\n\nПоэтому есть два пути. Силы и моменты: F = ma для центра вместе с M = I * alpha, замкнутые связью a = alpha * R. Или энергия: m g h = (1/2) m v^2 + (1/2) I omega^2 — это быстрее, когда спрашивают только скорость."}, "kk": {"heading": "Үйкеліс не үшін керек", "body": "Денені бірдеңе айналдыруы керек, ал центрге түсірілген ауырлық күші центрге қатысты момент жасамайды. Мұны жанасу нүктесіндегі тыныштық үйкеліс күші жасайды: иіні бар жалғыз күш сол, сондықтан бұрыштық үдеуді де сол анықтайды.\n\nЖанасу нүктесі лездік тыныштықта болғандықтан, үйкеліс күші орын ауыстырусыз әсер етеді, демек жұмыс істемейді. Энергия сақталады, бірақ бөлінеді: бір бөлігі центрдің қозғалысына, бір бөлігі айналуға кетеді, ал үлесті инерция моменті шешеді.\n\nСондықтан екі жол бар. Күштер мен моменттер: центр үшін F = ma және M = I * alpha, оларды a = alpha * R байланысы тұйықтайды. Немесе энергия: m g h = (1/2) m v^2 + (1/2) I omega^2 — тек жылдамдық сұралғанда бұл тезірек."}}$j$::jsonb where lesson_id = 'mechanics-connected-bodies' and position = 5;
update public.lesson_blocks set i18n = $j${"ru": {"heading": "Стоит запомнить", "items": ["Качение без проскальзывания: v = omega R и a = alpha R.", "Сила трения покоя в точке касания не совершает работы: точка её приложения неподвижна.", "Момент относительно центра создаёт только трение; сила тяжести проходит через центр.", "Кинетическая энергия катящегося тела: (1/2) m v^2 + (1/2) I omega^2.", "Сплошной цилиндр относительно оси: I = (1/2) m R^2. Сплошной шар: (2/5) m R^2. Обруч: m R^2.", "Чем больше I / (m R^2), тем больше энергии уходит во вращение и тем медленнее тело скатывается."]}, "kk": {"heading": "Есте сақтаған жөн", "items": ["Сырғанаусыз домалау: v = omega R және a = alpha R.", "Жанасу нүктесіндегі тыныштық үйкеліс күші жұмыс істемейді — ол түсірілген нүкте қозғалмайды.", "Центрге қатысты моментті тек үйкеліс жасайды; ауырлық күші центр арқылы өтеді.", "Домалайтын дененің кинетикалық энергиясы: (1/2) m v^2 + (1/2) I omega^2.", "Тұтас цилиндр өз осіне қатысты: I = (1/2) m R^2. Тұтас шар: (2/5) m R^2. Шеңбер (құрсау): m R^2.", "I / (m R^2) неғұрлым үлкен болса, соғұрлым көп энергия айналуға кетеді және дене баяу төмен түседі."]}}$j$::jsonb where lesson_id = 'mechanics-connected-bodies' and position = 6;
update public.lesson_blocks set i18n = $j${"ru": {"heading": "Деление с остатком", "body": "Для любых целых a и n > 0 существуют единственные q и r такие, что\n\n    a = q n + r,   0 <= r < n\n\nЭто весь фундамент. Остаток r — это и есть «a mod n», а любое утверждение о делимости — утверждение о том, что r равен нулю.\n\nПростые числа — мультипликативные атомы: каждое целое число больше 1 раскладывается на простые множители единственным образом с точностью до порядка. Единственность здесь реально работает: именно поэтому рассуждение о разложении одной части уравнения ограничивает другую."}, "kk": {"heading": "Қалдықпен бөлу", "body": "Кез келген бүтін a және n > 0 үшін мынадай жалғыз q мен r бар:\n\n    a = q n + r,   0 <= r < n\n\nБүкіл негіз осы. r қалдығы — «a mod n» дегеннің өзі, ал бөлінгіштік туралы кез келген тұжырым — r нөлге тең деген тұжырым.\n\nЖай сандар — мультипликативтік атомдар: 1-ден үлкен әр бүтін сан ретін есепке алмағанда жай көбейткіштерге бір ғана тәсілмен жіктеледі. Мұнда жалғыздық шын мәнінде жұмыс істейді: теңдеудің бір жағының жіктелуі туралы пайымдау екінші жағын шектейтіні сондықтан."}}$j$::jsonb where lesson_id = 'number-theory-divisibility' and position = 0;
update public.lesson_blocks set i18n = $j${"ru": {"heading": "НОД без разложения на множители", "body": "Раскладывать два больших числа на простые, чтобы сравнить множители, долго, а для по-настоящему больших чисел безнадёжно. Алгоритм Евклида обходится без этого благодаря одному наблюдению:\n\n    НОД(a, b) = НОД(b, a mod b)\n\nВсё, что делит и a, и b, делит и остаток, поэтому замена пары на меньшую ничего не теряет. Повторяйте, пока остаток не станет нулём; последний ненулевой остаток и есть НОД.\n\nРаботает и в обратную сторону. Если раскрутить шаги назад, НОД выражается через исходные числа: НОД(a,b) = ax + by для некоторых целых x и y — соотношение Безу. Именно оно позволяет вычислять обратные по модулю: a обратимо по модулю n ровно тогда, когда НОД(a,n) = 1, и обратный ход даёт сам обратный элемент."}, "kk": {"heading": "Жіктемей ЕҮОБ табу", "body": "Көбейткіштерді салыстыру үшін екі үлкен санды жай көбейткіштерге жіктеу ұзақ, ал шын мәнінде үлкен сандар үшін үмітсіз. Евклид алгоритмі бір бақылаудың арқасында онсыз-ақ шығады:\n\n    ЕҮОБ(a, b) = ЕҮОБ(b, a mod b)\n\na-ны да, b-ны да бөлетін кез келген сан қалдықты да бөледі, сондықтан жұпты кішірек жұппен ауыстыру ештеңе жоғалтпайды. Қалдық нөл болғанша қайталаңыз; соңғы нөлдік емес мән — ЕҮОБ.\n\nКері бағытта да жұмыс істейді. Қадамдарды кері айналдырсаңыз, ЕҮОБ бастапқы сандар арқылы өрнектеледі: кейбір бүтін x және y үшін ЕҮОБ(a,b) = ax + by — Безу теңдігі. Модуль бойынша кері элементтерді есептеуге мүмкіндік беретін де осы: a n модулі бойынша ЕҮОБ(a,n) = 1 болғанда ғана кері элементі бар, ал кері жүріс оны береді."}}$j$::jsonb where lesson_id = 'number-theory-divisibility' and position = 1;
update public.lesson_blocks set i18n = $j${"ru": {"heading": "НОД(1071, 462)", "body": "    1071 = 2 * 462 + 147\n     462 = 3 * 147 + 21\n     147 = 7 * 21  + 0\n\nПоследний ненулевой остаток — 21, значит НОД(1071, 462) = 21.\n\nТри строки, никакого разложения, и те же три строки сработали бы для сороказначных чисел. Обратный ход даёт 21 = 462 - 3*147 = 462 - 3*(1071 - 2*462) = 7*462 - 3*1071 — соотношение Безу для этой пары."}, "kk": {"heading": "ЕҮОБ(1071, 462)", "body": "    1071 = 2 * 462 + 147\n     462 = 3 * 147 + 21\n     147 = 7 * 21  + 0\n\nСоңғы нөлдік емес қалдық — 21, демек ЕҮОБ(1071, 462) = 21.\n\nҮш жол, ешқандай жіктеу жоқ, және қырық таңбалы сандар үшін де дәл осы үш жол жарар еді. Кері жүріс 21 = 462 - 3*147 = 462 - 3*(1071 - 2*462) = 7*462 - 3*1071 береді — бұл жұп үшін Безу теңдігі."}}$j$::jsonb where lesson_id = 'number-theory-divisibility' and position = 2;
update public.lesson_blocks set i18n = $j${"ru": {"heading": "Стоит запомнить", "items": ["a = qn + r, 0 <= r < n, единственным образом. «a mod n» — это r.", "Каждое целое число больше 1 раскладывается на простые множители единственным образом с точностью до порядка.", "НОД(a,b) = НОД(b, a mod b). Повторяйте, пока остаток не станет нулём.", "НОД(a,b) * НОК(a,b) = a*b.", "Безу: НОД(a,b) = ax + by для некоторых целых x, y.", "a обратимо по модулю n ровно тогда, когда НОД(a,n) = 1."]}, "kk": {"heading": "Есте сақтаған жөн", "items": ["a = qn + r, 0 <= r < n, жалғыз тәсілмен. «a mod n» — сол r.", "1-ден үлкен әр бүтін санның ретін есепке алмағанда жалғыз жай көбейткіштерге жіктелуі бар.", "ЕҮОБ(a,b) = ЕҮОБ(b, a mod b). Қалдық нөл болғанша қайталаңыз.", "ЕҮОБ(a,b) * ЕКОЕ(a,b) = a*b.", "Безу: кейбір бүтін x, y үшін ЕҮОБ(a,b) = ax + by.", "a n модулі бойынша ЕҮОБ(a,n) = 1 болғанда ғана кері айналады."]}}$j$::jsonb where lesson_id = 'number-theory-divisibility' and position = 3;
update public.lesson_blocks set i18n = $j${"ru": {"heading": "Работа с показателем", "body": "Сравнения складываются, вычитаются и перемножаются в точности как уравнения — поэтому их и стоит составлять. Исключение — деление: сокращать на множитель можно, только если он обратим по модулю n.\n\nДля степеней полезна идея порядка — наименьшего k, при котором a^k сравнимо с 1 по модулю n. Зная его, любой показатель можно уменьшить по модулю k, и вопрос про a^1000 превращается в вопрос про небольшое число.\n\nМалая теорема Ферма даёт такой показатель бесплатно: если p простое и не делит a, то a^(p-1) сравнимо с 1 по модулю p. Теорема Эйлера обобщает её на любой модуль, с phi(n) вместо p-1."}, "kk": {"heading": "Дәреже көрсеткішімен жұмыс", "body": "Салыстырулар теңдеулер сияқты дәл қосылады, азайтылады және көбейтіледі — оларды құрудың мәні де сонда. Ерекшелік — бөлу: көбейткішке қысқартуға ол n модулі бойынша кері айналатын болғанда ғана болады.\n\nДәрежелер үшін рет идеясы пайдалы — a^k саны n модулі бойынша 1-мен салыстырылатын ең кіші k. Оны білсеңіз, кез келген көрсеткішті k модулі бойынша азайтуға болады, және a^1000 туралы сұрақ кішкентай сан туралы сұраққа айналады.\n\nФерманың кіші теоремасы мұны тегін береді: p жай сан және a-ны бөлмесе, a^(p-1) саны p модулі бойынша 1-мен салыстырылады. Эйлер теоремасы оны кез келген модульге жалпылайды, p-1 орнына phi(n)."}}$j$::jsonb where lesson_id = 'number-theory-divisibility' and position = 4;
update public.lesson_blocks set i18n = $j${"ru": {"heading": "Последняя цифра 7^100", "body": "Последняя цифра — это значение по модулю 10, поэтому ищем порядок числа 7.\n\n    7^1 = 7,  7^2 = 49 -> 9,  7^3 -> 3,  7^4 -> 1  (mod 10)\n\nПорядок равен 4. Так как 100 = 4 * 25, 7^100 сравнимо с (7^4)^25 = 1^25 = 1 по модулю 10.\n\nПоследняя цифра — 1, и для этого не понадобилось вычислять ни одну из восьмидесяти пяти цифр числа 7^100."}, "kk": {"heading": "7^100 санының соңғы цифры", "body": "Соңғы цифр — 10 модулі бойынша мән, сондықтан 7 санының ретін іздейміз.\n\n    7^1 = 7,  7^2 = 49 -> 9,  7^3 -> 3,  7^4 -> 1  (mod 10)\n\nРеті 4. 100 = 4 * 25 болғандықтан, 7^100 саны 10 модулі бойынша (7^4)^25 = 1^25 = 1-мен салыстырылады.\n\nСоңғы цифр — 1, және бұл үшін 7^100 санының сексен бес цифрының бірін де есептеу қажет болмады."}}$j$::jsonb where lesson_id = 'number-theory-divisibility' and position = 5;
update public.lesson_blocks set i18n = $j${"ru": {"heading": "Стоит запомнить", "items": ["Сравнения можно свободно складывать, вычитать и перемножать; для сокращения нужен обратимый множитель.", "Порядок a по модулю n — наименьшее k, при котором a^k = 1. Показатели тогда уменьшаются по модулю k.", "Ферма: для простого p, не делящего a, a^(p-1) = 1 mod p.", "Эйлер: a^phi(n) = 1 mod n, если НОД(a,n) = 1.", "Китайская теорема об остатках: по взаимно простым модулям можно решать отдельно и затем собрать ответ.", "Последняя цифра — это mod 10; две последние — mod 100. Ничего загадочнее."]}, "kk": {"heading": "Есте сақтаған жөн", "items": ["Салыстыруларды еркін қосуға, азайтуға және көбейтуге болады; қысқарту үшін кері айналатын көбейткіш керек.", "a-ның n модулі бойынша реті — a^k = 1 болатын ең кіші k. Сонда көрсеткіштер k модулі бойынша азаяды.", "Ферма: a-ны бөлмейтін жай p үшін a^(p-1) = 1 mod p.", "Эйлер: ЕҮОБ(a,n) = 1 болса, a^phi(n) = 1 mod n.", "Қалдықтар туралы қытай теоремасы: өзара жай модульдер бойынша бөлек шешіп, кейін біріктіруге болады.", "Соңғы цифр — mod 10; соңғы екі цифр — mod 100. Одан басқа жұмбақ жоқ."]}}$j$::jsonb where lesson_id = 'number-theory-divisibility' and position = 6;
update public.lesson_blocks set i18n = $j${"ru": {"heading": "Энергия на входе, энергия на выходе", "body": "Первое начало термодинамики — это закон сохранения энергии, где два способа передачи энергии названы отдельно:\n\n    delta U = Q - W\n\nQ — теплота, подведённая к газу. W — работа, совершённая газом над окружением. Остаток меняет U — внутреннюю энергию.\n\nЗнак минус и есть всё содержание соглашения: расширяясь, газ давит на окружающий мир, тратит на это энергию и остывает, если теплота не восполняет потраченное. В некоторых книгах пишут delta U = Q + W, где W — работа над газом. Оба варианта верны; смешивать их — нет."}, "kk": {"heading": "Кірген энергия, шыққан энергия", "body": "Бірінші заң — энергияны берудің екі тәсілі бөлек аталған энергияның сақталу заңы:\n\n    delta U = Q - W\n\nQ — газға берілген жылу. W — газдың қоршаған ортаға жасаған жұмысы. Қалғаны U ішкі энергиясын өзгертеді.\n\nМинус таңбасы — келісімнің бүкіл мазмұны: ұлғайған газ қоршаған әлемге қысым түсіреді, оған энергия жұмсайды және жылу жұмсалғанды толтырмаса, суиды. Кейбір кітаптарда delta U = Q + W деп жазады, мұнда W — газға жасалған жұмыс. Екеуі де дұрыс; оларды араластыру — дұрыс емес."}}$j$::jsonb where lesson_id = 'thermodynamics-first-law' and position = 0;
update public.lesson_blocks set i18n = $j${"ru": {"heading": "Работа — это площадь, а не формула", "body": "Когда газ расширяется на dV при давлении p, он совершает работу p dV, поэтому за весь процесс\n\n    W = интеграл p dV\n\nа это в точности площадь под графиком процесса на pV-диаграмме. Поэтому диаграмму и стоит рисовать: работа на ней видна.\n\nОтсюда сразу три следствия. Вертикальная линия не ограничивает площади, поэтому изохорный участок не совершает работы вовсе. Горизонтальная линия даёт прямоугольник, поэтому изобарный участок совершает работу p * delta V. А замкнутый цикл возвращает газ в исходное состояние, поэтому за цикл delta U = 0 и полезная работа равна площади внутри цикла — теплота на входе, работа на выходе, ничего не накапливается.\n\nНаправление обхода задаёт знак. По часовой стрелке — газ расширяется при большем давлении, а сжимается при меньшем, поэтому работы выходит больше, чем вкладывается: это двигатель. Против часовой — та же машина, запущенная в обратную сторону: она забирает работу, чтобы переносить теплоту, — холодильник."}, "kk": {"heading": "Жұмыс — формула емес, аудан", "body": "Газ p қысымына қарсы dV-ға ұлғайғанда, ол p dV жұмыс жасайды, сондықтан бүкіл процесс бойында\n\n    W = p dV интегралы\n\nал бұл pV-диаграммадағы процесс сызығы астындағы аудан. Диаграмманы сызудың мәні де сонда: жұмыс көрініп тұрады.\n\nБұдан бірден үш салдар шығады. Тік сызық аудан шектемейді, сондықтан изохоралық қадам мүлде жұмыс жасамайды. Көлденең сызық тіктөртбұрыш береді, сондықтан изобаралық қадам p * delta V жұмыс жасайды. Ал тұйық цикл газды бастапқы күйіне қайтарады, сондықтан цикл бойы delta U = 0 және пайдалы жұмыс цикл шектеген ауданға тең — жылу кіреді, жұмыс шығады, ештеңе жиналмайды.\n\nАйналу бағыты таңбаны шешеді. Сағат тілімен — газ жоғарырақ қысымда ұлғайып, төменірек қысымда сығылады, сондықтан жұмсалғаннан көп жұмыс шығады: бұл қозғалтқыш. Сағат тіліне қарсы — сол машина кері жұмыс істейді: жылуды тасымалдау үшін жұмыс алады — тоңазытқыш."}}$j$::jsonb where lesson_id = 'thermodynamics-first-law' and position = 1;
update public.lesson_blocks set i18n = $j${"ru": {"heading": "Один изобарный участок от начала до конца", "body": "Газ расширяется при постоянном давлении 2,0 * 10^5 Па от 1,0 л до 3,0 л, получая 900 Дж теплоты.\n\n    delta V = 3,0 - 1,0 = 2,0 л = 2,0 * 10^-3 м^3\n    W = p * delta V = 2,0*10^5 * 2,0*10^-3 = 400 Дж   (совершена газом)\n    delta U = Q - W = 900 - 400 = 500 Дж\n\nИз 900 Дж, которые поступили, 400 Дж ушли обратно в виде работы над окружением, а 500 Дж остались внутренней энергией — для идеального газа это значит, что температура выросла.\n\nЕсли бы тот же газ нагревали в закрытом жёстком сосуде, W было бы равно нулю и все 900 Дж ушли бы в U."}, "kk": {"heading": "Бір изобаралық қадам басынан аяғына дейін", "body": "Газ тұрақты 2,0 * 10^5 Па қысымда 1,0 л-ден 3,0 л-ге дейін ұлғайып, 900 Дж жылу алады.\n\n    delta V = 3,0 - 1,0 = 2,0 л = 2,0 * 10^-3 м^3\n    W = p * delta V = 2,0*10^5 * 2,0*10^-3 = 400 Дж   (газ жасаған)\n    delta U = Q - W = 900 - 400 = 500 Дж\n\nКірген 900 Дж-дің 400 Дж-і қоршаған ортаға жұмыс ретінде қайта шықты, ал 500 Дж ішкі энергия болып қалды — идеал газ үшін бұл температура өсті дегенді білдіреді.\n\nЕгер сол газ тұйық қатты ыдыста қыздырылса, W нөлге тең болар еді және 900 Дж түгел U-ға кетер еді."}}$j$::jsonb where lesson_id = 'thermodynamics-first-law' and position = 2;
update public.lesson_blocks set i18n = $j${"ru": {"heading": "Стоит запомнить", "items": ["delta U = Q - W, где W — работа газа. Назовите своё соглашение, прежде чем начинать.", "W — площадь под процессом на pV-диаграмме; полезная работа за цикл — площадь внутри цикла.", "Изохорный: W = 0. Изобарный: W = p delta V. Изотермический для идеального газа: delta U = 0, значит Q = W.", "Адиабатный: Q = 0, значит delta U = -W — газ остывает, расширяясь.", "У идеального газа U зависит только от температуры: delta U = n Cv delta T в любом процессе, а не только при постоянном объёме.", "Цикл по часовой стрелке: работа на выходе, двигатель. Против часовой: работа на входе, холодильник."]}, "kk": {"heading": "Есте сақтаған жөн", "items": ["delta U = Q - W, мұнда W — газдың жұмысы. Бастамас бұрын келісіміңізді атаңыз.", "W — pV-диаграммадағы процесс астындағы аудан; бір циклдегі пайдалы жұмыс — цикл ішіндегі аудан.", "Изохоралық: W = 0. Изобаралық: W = p delta V. Идеал газдың изотермиялық процесі: delta U = 0, демек Q = W.", "Адиабаталық: Q = 0, демек delta U = -W — газ ұлғайғанда суиды.", "Идеал газ үшін U тек температураға тәуелді: delta U = n Cv delta T кез келген процесте, тек тұрақты көлемде ғана емес.", "Сағат тілімен цикл: жұмыс шығады, қозғалтқыш. Сағат тіліне қарсы: жұмыс кіреді, тоңазытқыш."]}}$j$::jsonb where lesson_id = 'thermodynamics-first-law' and position = 3;
update public.lesson_blocks set i18n = $j${"ru": {"heading": "Отношение чего — КПД", "body": "Для цикла КПД — это то, что хотели получить, делённое на то, за что заплатили:\n\n    eta = W_полезн / Q_получ\n\nW_полезн — площадь внутри цикла. Q_получ — полученная теплота: сумма по тем участкам, где теплота поступает в газ, и только по ним. Теплота, отданная на других участках, не уменьшает Q_получ — именно из-за неё eta и меньше 1.\n\nПонять, на каких участках газ получает теплоту, — бо́льшая часть работы в таких задачах. Идите участок за участком по первому началу и оставляйте положительные."}, "kk": {"heading": "ПӘК — неге қатынас", "body": "Цикл үшін ПӘК — алғыңыз келгенді төлегеніңізге бөлгені:\n\n    eta = W_пайд / Q_алын\n\nW_пайд — цикл ішіндегі аудан. Q_алын — алынған жылу: газға жылу кіретін бөліктер бойынша қосынды, тек солар бойынша. Циклдің басқа бөліктерінде берілген жылу Q_алын-ды азайтпайды — eta-ның 1-ден кіші болатыны да сол үшін.\n\nҚай бөліктерде газ жылу алатынын анықтау — мұндай есептердегі жұмыстың басым бөлігі. Бірінші заң бойынша бөлік-бөлікпен жүріп, оңдарын қалдырыңыз."}}$j$::jsonb where lesson_id = 'thermodynamics-first-law' and position = 4;
update public.lesson_blocks set i18n = $j${"ru": {"heading": "Стоит запомнить", "items": ["eta = W_полезн / Q_получ, где Q_получ учитывает только участки, на которых теплота поступает.", "Находите Q на каждом участке из delta U = Q - W; не берите в знаменатель суммарную теплоту.", "Ни один цикл между двумя температурами не превзойдёт КПД Карно 1 - Tх / Tн, температуры в кельвинах.", "Реальный цикл, КПД которого выше предела Карно, — арифметическая ошибка, а не открытие."]}, "kk": {"heading": "Есте сақтаған жөн", "items": ["eta = W_пайд / Q_алын, мұнда Q_алын тек жылу кіретін бөліктерді есептейді.", "Q-ды әр бөлікте delta U = Q - W арқылы табыңыз; бөлімге жиынтық жылуды қоймаңыз.", "Екі температура арасындағы ешбір цикл Карно мәнінен 1 - Tс / Tқ асып түспейді, T кельвинмен.", "ПӘК-і Карно шегінен жоғары деп көрсетілген нақты цикл — жаңалық емес, арифметикалық қате."]}}$j$::jsonb where lesson_id = 'thermodynamics-first-law' and position = 5;

update public.quiz_questions set i18n = $j${"ru": {"prompt": "Для уравнения 3x^2 - 12x + 5 = 0 сумма корней равна", "options": ["4", "-4", "12", "5/3"], "explanation": "Сумма равна -b/a = -(-12)/3 = 4. Второй вариант забывает знак минус в формуле; 5/3 — это произведение."}, "kk": {"prompt": "3x^2 - 12x + 5 = 0 теңдеуінің түбірлерінің қосындысы", "options": ["4", "-4", "12", "5/3"], "explanation": "Қосынды -b/a = -(-12)/3 = 4. Екінші нұсқа формуладағы минус таңбасын ұмытады; 5/3 — көбейтінді."}}$j$::jsonb where id = 'alg-q1';
update public.quiz_questions set i18n = $j${"ru": {"prompt": "Если r+s = 5 и rs = 6, то r^2 + s^2 равно", "options": ["13", "25", "37", "11"], "explanation": "(r+s)^2 - 2rs = 25 - 12 = 13. Квадрат суммы сам по себе даёт 25 и дважды учитывает перекрёстное слагаемое — его и убирает вычитание."}, "kk": {"prompt": "Егер r+s = 5 және rs = 6 болса, r^2 + s^2 тең", "options": ["13", "25", "37", "11"], "explanation": "(r+s)^2 - 2rs = 25 - 12 = 13. Қосындының квадраты өзі 25 береді және айқас мүшені екі рет есептейді — шегеру соны алып тастайды."}}$j$::jsonb where id = 'alg-q2';
update public.quiz_questions set i18n = $j${"ru": {"prompt": "p(x) делится на (x - 3) без остатка. Что из этого следует?", "options": ["p(3) = 0, значит (x-3) — множитель", "p(0) = 3", "3 — старший коэффициент", "p(x) имеет степень 3"], "explanation": "Остаток от деления на (x-k) равен p(k), поэтому нулевой остаток значит p(3) = 0 и (x-3) делит p. Это теорема о множителе: проверка корня превращается в подстановку."}, "kk": {"prompt": "p(x) (x - 3)-ке қалдықсыз бөлінеді. Бұдан не шығады?", "options": ["p(3) = 0, демек (x-3) — көбейткіш", "p(0) = 3", "3 — жоғарғы коэффициент", "p(x) дәрежесі 3"], "explanation": "(x-k)-ға бөлгендегі қалдық p(k), сондықтан нөлдік қалдық p(3) = 0 және (x-3) p-ны бөледі дегенді білдіреді. Бұл көбейткіш туралы теорема: түбірді тексеру қоюға айналады."}}$j$::jsonb where id = 'alg-q3';
update public.quiz_questions set i18n = $j${"ru": {"prompt": "Квадратное уравнение, у которого сумма корней 7, а произведение 10:", "options": ["x^2 - 7x + 10 = 0", "x^2 + 7x + 10 = 0", "x^2 - 10x + 7 = 0", "x^2 + 7x - 10 = 0"], "explanation": "x^2 - (сумма)x + (произведение) = 0. Знак у суммы меняется, а у произведения — нет; в этом ошибка второго варианта, а в третьем они перепутаны местами."}, "kk": {"prompt": "Түбірлерінің қосындысы 7, көбейтіндісі 10 болатын квадрат теңдеу", "options": ["x^2 - 7x + 10 = 0", "x^2 + 7x + 10 = 0", "x^2 - 10x + 7 = 0", "x^2 + 7x - 10 = 0"], "explanation": "x^2 - (қосынды)x + (көбейтінді) = 0. Қосындының таңбасы ауысады, көбейтіндінікі — жоқ; екінші нұсқаның қатесі осы, ал үшіншісінде олар орын ауыстырған."}}$j$::jsonb where id = 'alg-q4';
update public.quiz_questions set i18n = $j${"ru": {"prompt": "У уравнения 2x^3 - 5x + 3 = 0 целые коэффициенты. Что может быть его рациональным корнем?", "options": ["3/2", "2/3", "5/2", "1/5"], "explanation": "У рационального корня p/q число p делит свободный член 3, а q — старший коэффициент 2. Это допускает ±1, ±3, ±1/2 и ±3/2 и исключает остальные. Является ли 3/2 корнем на самом деле — проверяется одной подстановкой."}, "kk": {"prompt": "2x^3 - 5x + 3 = 0 теңдеуінің коэффициенттері бүтін. Қайсысы рационал түбір бола алады?", "options": ["3/2", "2/3", "5/2", "1/5"], "explanation": "p/q рационал түбірінде p бос мүше 3-ті, q жоғарғы коэффициент 2-ні бөлуі керек. Бұл ±1, ±3, ±1/2 және ±3/2-ні рұқсат етіп, қалғандарын жоққа шығарады. 3/2 шынымен түбір ме — бір қою арқылы тексеріледі."}}$j$::jsonb where id = 'alg-q5';
update public.quiz_questions set i18n = $j${"ru": {"prompt": "У квадратного уравнения с действительными коэффициентами дискриминант b^2 - 4ac < 0. Его корни —", "options": ["пара комплексно сопряжённых", "два различных действительных числа", "одно кратное действительное число", "не определены"], "explanation": "Отрицательный дискриминант даёт квадратный корень из отрицательного числа, то есть сопряжённую пару. При нуле был бы кратный корень, при положительном — два различных действительных. Корни существуют в любом случае: над комплексными числами у многочлена степени n их всегда n."}, "kk": {"prompt": "Нақты квадрат теңдеудің дискриминанты b^2 - 4ac < 0. Оның түбірлері —", "options": ["түйіндес комплекс жұп", "екі әртүрлі нақты сан", "бір еселі нақты сан", "анықталмаған"], "explanation": "Теріс дискриминант формулада теріс санның квадрат түбірін береді, яғни түйіндес жұп. Нөлде еселі түбір, оң болғанда екі әртүрлі нақты түбір болар еді. Түбірлер кез келген жағдайда бар — комплекс сандар үстінде n-дәрежелі көпмүшенің әрдайым n түбірі бар."}}$j$::jsonb where id = 'alg-q6';
update public.quiz_questions set i18n = $j${"ru": {"prompt": "Сколькими способами можно выбрать комиссию из 3 человек из 8, если должностей нет?", "options": ["56", "336", "24", "512"], "explanation": "Порядок не важен, значит это C(8,3) = 8*7*6/6 = 56. Число 336 — это P(8,3): оно считает каждую комиссию столько раз, сколькими способами её можно упорядочить, то есть 3! раз."}, "kk": {"prompt": "Лауазымсыз 3 адамнан тұратын комиссияны 8 адамнан неше тәсілмен таңдауға болады?", "options": ["56", "336", "24", "512"], "explanation": "Рет маңызды емес, демек бұл C(8,3) = 8*7*6/6 = 56. 336 — P(8,3): ол әр комиссияны оны реттеудің 3! тәсілінің әрқайсысы үшін бір рет санайды."}}$j$::jsonb where id = 'comb-q1';
update public.quiz_questions set i18n = $j${"ru": {"prompt": "C(10,7) равно", "options": ["C(10,3)", "у C(10,7) нет более простой записи", "C(7,3)", "C(10,4)"], "explanation": "C(n,k) = C(n,n-k): выбрать 7, которых взять, — то же, что выбрать 3, которых оставить. Это превращает тяжёлое вычисление в 10*9*8/6 = 120."}, "kk": {"prompt": "C(10,7) тең", "options": ["C(10,3)", "C(10,7)-нің қарапайым түрі жоқ", "C(7,3)", "C(10,4)"], "explanation": "C(n,k) = C(n,n-k): алатын 7-ні таңдау — қалдыратын 3-ті таңдау. Мұны пайдалану ауыр есептеуді 10*9*8/6 = 120-ға айналдырады."}}$j$::jsonb where id = 'comb-q2';
update public.quiz_questions set i18n = $j${"ru": {"prompt": "Правильную монету бросают 5 раз. Какова вероятность хотя бы одного орла?", "options": ["31/32", "1/32", "5/32", "1/2"], "explanation": "Посчитайте противоположное. Неудача — только все пять решек, это 1/32, значит хотя бы один орёл — 31/32. Складывать случаи «один орёл», «два орла» и так далее — тот же ответ ценой гораздо большей работы."}, "kk": {"prompt": "Әділ тиын 5 рет лақтырылады. Кемінде бір рет елтаңба түсу ықтималдығы қандай?", "options": ["31/32", "1/32", "5/32", "1/2"], "explanation": "Қарсысын санаңыз. Сәтсіздік — тек бесеуі де сан, бұл 1/32, демек кемінде бір елтаңба — 31/32. «Бір елтаңба», «екі елтаңба» және т.с.с. жағдайларды қосу сол жауапты әлдеқайда көп жұмыспен береді."}}$j$::jsonb where id = 'comb-q3';
update public.quiz_questions set i18n = $j${"ru": {"prompt": "В классе 30 человек: 18 учат французский, 15 — немецкий, 8 — оба. Сколько учат хотя бы один?", "options": ["25", "33", "22", "30"], "explanation": "18 + 15 = 33 дважды считает тех 8, кто учит оба, — вычтем их один раз: 25. Число 33 — ровно та ошибка, которую исправляет формула включений-исключений."}, "kk": {"prompt": "30 оқушысы бар сыныпта 18-і француз, 15-і неміс тілін оқиды, 8-і екеуін де оқиды. Кемінде біреуін неше оқушы оқиды?", "options": ["25", "33", "22", "30"], "explanation": "18 + 15 = 33 екеуін де оқитын 8-ді екі рет санайды, сондықтан оларды бір рет шегереміз: 25. 33 — қосу-шегеру формуласы түзету үшін бар дәл сол қате."}}$j$::jsonb where id = 'comb-q4';
update public.quiz_questions set i18n = $j${"ru": {"prompt": "В комнате тринадцать человек. Что гарантирует принцип Дирихле про месяцы их рождения?", "options": ["Хотя бы двое родились в одном месяце", "В каждом месяце кто-то родился", "Хотя бы двое родились в один день", "Ничего, если не знать дней рождения"], "explanation": "Тринадцать предметов, двенадцать ящиков: в каком-то ящике два. Принцип обещает существование, но не говорит, какой ящик, — и ничего не утверждает о том, что заполнены все месяцы."}, "kk": {"prompt": "Бөлмеде он үш адам бар. Дирихле принципі олардың туған айлары туралы нені кепілдейді?", "options": ["Кемінде екеуі бір айда туған", "Әр айда біреу туған", "Кемінде екеуі бір күні туған", "Туған күндерді білмей ештеңе"], "explanation": "Он үш зат, он екі жәшік: бір жәшікте екеуі бар. Принцип бар екенін уәде етеді, бірақ қай жәшік екенін айтпайды — және барлық айлар толы деп ештеңе айтпайды."}}$j$::jsonb where id = 'comb-q5';
update public.quiz_questions set i18n = $j${"ru": {"prompt": "Сколькими способами можно раздать 6 одинаковых конфет 3 разным детям, если кому-то может не достаться ни одной?", "options": ["28", "18", "729", "120"], "explanation": "Шары и перегородки: 6 одинаковых предметов по 3 различным ящикам — C(6+3-1, 3-1) = C(8,2) = 28. Именно одинаковость конфет не даёт ответу быть 3^6."}, "kk": {"prompt": "6 бірдей кәмпитті 3 түрлі балаға біреуіне ешқайсысы тимеуі мүмкін болып, неше тәсілмен таратуға болады?", "options": ["28", "18", "729", "120"], "explanation": "Шарлар мен бөгеттер: 6 бірдей затты 3 таңбаланған жәшікке — C(6+3-1, 3-1) = C(8,2) = 28. Кәмпиттердің бірдей болуы жауапты 3^6 болудан сақтайды."}}$j$::jsonb where id = 'comb-q6';
update public.quiz_questions set i18n = $j${"ru": {"prompt": "Что происходит с сопротивлением провода, если увеличить его длину, не меняя материал и сечение?", "options": ["Растёт пропорционально длине", "Падает пропорционально длине", "Растёт как квадрат длины", "Не меняется — сопротивление является свойством материала"], "explanation": "R = rho L / A, значит R пропорционально L: при том же напряжении носителям нужно пройти дальше и пережить больше столкновений. Квадратичная зависимость появляется только тогда, когда одновременно меняется площадь, как при растяжении провода."}, "kk": {"prompt": "Материал мен қима өзгермей, сымның ұзындығы артса, кедергісі не болады?", "options": ["Ұзындыққа пропорционал өседі", "Ұзындыққа пропорционал азаяды", "Ұзындықтың квадратымен өседі", "Өзгермейді — кедергі материалдың қасиеті"], "explanation": "R = rho L / A, демек R L-ге пропорционал: сол кернеуде тасымалдаушыларға алысырақ жүріп, көбірек соқтығысуға төтеп беру керек. Квадраттық тәуелділік аудан бір мезгілде өзгергенде ғана пайда болады, сымды созғандағыдай."}}$j$::jsonb where id = 'elec-q1';
update public.quiz_questions set i18n = $j${"ru": {"prompt": "Провод растянули вдвое, его объём не изменился. Сопротивление стало", "options": ["в 4 раза больше исходного", "в 2 раза больше исходного", "в 2 раза меньше исходного", "прежним, ведь это тот же кусок металла"], "explanation": "Постоянный объём значит, что L * A не меняется, поэтому при удвоении L площадь A уменьшается вдвое. R = rho L / A получает множитель 2 от длины и ещё 2 от площади: всего в четыре раза."}, "kk": {"prompt": "Сымды көлемін өзгертпей екі есе ұзарғанша созды. Оның кедергісі", "options": ["бастапқыдан 4 есе көп", "бастапқыдан 2 есе көп", "бастапқының жартысы", "өзгермейді, өйткені бұл сол металл"], "explanation": "Тұрақты көлем L * A өзгермейді дегенді білдіреді, сондықтан L екі еселенгенде A екі есе азаяды. R = rho L / A ұзындықтан 2 көбейткішін және аудан арқылы тағы 2 алады: барлығы төрт есе."}}$j$::jsonb where id = 'elec-q2';
update public.quiz_questions set i18n = $j${"ru": {"prompt": "Два провода из одного материала и одной длины отличаются только диаметром: один вдвое толще другого. Как соотносятся их сопротивления?", "options": ["У толстого сопротивление в четыре раза меньше", "У толстого сопротивление в два раза меньше", "У толстого сопротивление в два раза больше", "Одинаковы — диаметра нет в формуле R = rho L / A"], "explanation": "В формуле стоит площадь, а она пропорциональна квадрату диаметра. Вдвое больший диаметр — вчетверо большая площадь, значит вчетверо меньшее сопротивление. Путать диаметр с площадью — обычная ошибка здесь."}, "kk": {"prompt": "Бір материалдан жасалған, ұзындығы бірдей екі сым тек диаметрімен ерекшеленеді: біреуі екіншісінен екі есе жуан. Кедергілері қалай салыстырылады?", "options": ["Жуанының кедергісі төрт есе аз", "Жуанының кедергісі екі есе аз", "Жуанының кедергісі екі есе көп", "Бірдей — R = rho L / A формуласында диаметр жоқ"], "explanation": "Формулада аудан тұр, ал аудан диаметрдің квадратына пропорционал. Екі есе үлкен диаметр — төрт есе үлкен аудан, демек кедергі төрт есе аз. Диаметрді аудан деп шатастыру — мұндағы әдеттегі қате."}}$j$::jsonb where id = 'elec-q3';
update public.quiz_questions set i18n = $j${"ru": {"prompt": "Удельное сопротивление rho зависит от", "options": ["материала и его температуры", "длины образца", "площади поперечного сечения", "текущего через него тока"], "explanation": "rho — то, что остаётся после того, как геометрия поделена: оно говорит, как ведёт себя вещество, а не какой формы из него вырезали образец. Температура его меняет: у металла — в сторону роста, у полупроводника — в сторону уменьшения."}, "kk": {"prompt": "Меншікті кедергі rho тәуелді", "options": ["материал мен оның температурасына", "үлгінің ұзындығына", "көлденең қима ауданына", "одан өтетін токқа"], "explanation": "rho — геометрияны бөліп тастағаннан кейін қалатын шама: ол заттың не істейтінін айтады, оның қандай пішінде кесілгенін емес. Температура оны өзгертеді: металда — жоғары, жартылай өткізгіште — төмен."}}$j$::jsonb where id = 'elec-q4';
update public.quiz_questions set i18n = $j${"ru": {"prompt": "Резисторы 6 Ом и 3 Ом соединены параллельно. Общее сопротивление —", "options": ["2 Ом", "4,5 Ом", "9 Ом", "18 Ом"], "explanation": "R = R1 R2 / (R1 + R2) = 18 / 9 = 2 Ом. Полезная проверка: параллельное соединение должно получиться меньше своего наименьшего элемента, а 2 меньше 3."}, "kk": {"prompt": "6 Ом және 3 Ом резисторлар параллель қосылған. Жалпы кедергі —", "options": ["2 Ом", "4,5 Ом", "9 Ом", "18 Ом"], "explanation": "R = R1 R2 / (R1 + R2) = 18 / 9 = 2 Ом. Пайдалы тексеру: параллель қосылыс өзінің ең кіші мүшесінен кіші болуы тиіс, ал 2 саны 3-тен кіші."}}$j$::jsonb where id = 'elec-q5';
update public.quiz_questions set i18n = $j${"ru": {"prompt": "К цепи параллельно добавили резистор. Общее сопротивление", "options": ["всегда уменьшается", "всегда увеличивается", "растёт или падает в зависимости от добавленного номинала", "не меняется"], "explanation": "Ещё одна параллельная ветвь — ещё один путь для тока, поэтому проводимость растёт, а сопротивление падает, каким бы большим ни был добавленный резистор. Последовательное соединение — зеркальный случай: добавление чего угодно всегда увеличивает общее сопротивление."}, "kk": {"prompt": "Бар тізбекке параллель резистор қосылды. Жалпы кедергі", "options": ["әрдайым азаяды", "әрдайым артады", "қосылған мәнге қарай артады немесе азаяды", "өзгермейді"], "explanation": "Тағы бір параллель тармақ — ток үшін тағы бір жол, сондықтан өткізгіштік артып, кедергі азаяды — қосылған резистор қаншалықты үлкен болса да. Тізбектей қосу — айнадағы бейнесі: кез келгенін қосу жалпы кедергіні әрдайым арттырады."}}$j$::jsonb where id = 'elec-q6';
update public.quiz_questions set i18n = $j${"ru": {"prompt": "Два бруска разной массы связаны лёгкой нерастяжимой нитью, и их тянут прямо по гладкому столу. Что верно для их ускорений?", "options": ["Равны по модулю", "Тяжёлый брусок ускоряется меньше", "Каждое обратно пропорционально массе своего бруска", "Они не связаны, пока не известно натяжение"], "explanation": "Нить не растягивается, поэтому если один её конец сдвинулся на некоторое расстояние за некоторое время, то и другой тоже. Одинаковое перемещение в каждый момент означает одинаковую скорость и одинаковое ускорение — при любых массах."}, "kk": {"prompt": "Массалары әртүрлі екі білеуше жеңіл созылмайтын жіппен байланып, тегіс үстел бойымен тура тартылады. Олардың үдеулері туралы не дұрыс?", "options": ["Модульдері тең", "Ауыр білеуше азырақ үдейді", "Әрқайсысы өз массасына кері пропорционал", "Керілу белгілі болмайынша байланыссыз"], "explanation": "Жіп созылмайды, сондықтан бір ұшы белгілі бір уақытта белгілі бір қашықтыққа жылжыса, екіншісі де солай жылжиды. Әр сәтте бірдей орын ауыстыру бірдей жылдамдық пен бірдей үдеуді білдіреді — массалар қандай болса да."}}$j$::jsonb where id = 'mech-q1';
update public.quiz_questions set i18n = $j${"ru": {"prompt": "Почему сложение уравнений Ньютона для пары связанных тел убирает натяжение?", "options": ["Потому что это внутренняя сила и в двух уравнениях она входит с противоположными знаками", "Потому что натяжение всегда настолько мало, что им можно пренебречь", "Потому что нить невесома и натяжение равно нулю", "Потому что два ускорения равны"], "explanation": "Каждое тело нить тянет с силой, равной натяжению; у лёгкой нити на блоке без трения натяжение по всей длине одинаково, поэтому две силы равны по модулю и в уравнениях, записанных вдоль движения каждого тела, имеют противоположные знаки. В сумме они сокращаются. Это не пара по третьему закону: каждая — действие нити на тело, а её пара — действие тела на нить. У невесомой нити натяжение не ноль, а одно и то же на обоих концах."}, "kk": {"prompt": "Байланысқан жұптың екі Ньютон теңдеуін қосу неге керілуді жояды?", "options": ["Өйткені бұл ішкі күш және екі теңдеуге қарама-қарсы таңбамен кіреді", "Өйткені керілу әрдайым ескермеуге болатындай аз", "Өйткені жіп салмақсыз, сондықтан керілу нөл", "Өйткені екі үдеу тең"], "explanation": "Әр денені жіп керілуге тең күшпен тартады; үйкеліссіз блок арқылы өткен жеңіл жіптің керілуі бүкіл бойында бірдей, сондықтан екі күштің модулі тең және әр дененің қозғалысы бойымен жазылған теңдеулерде таңбалары қарама-қарсы. Қосындыда олар қысқарады. Бұл үшінші заң бойынша жұп емес — әрқайсысы жіптің денеге әсері, ал оның жұбы — дененің жіпке әсері. Салмақсыз жіптің керілуі нөл емес; оның екі ұшында керілу бірдей."}}$j$::jsonb where id = 'mech-q2';
update public.quiz_questions set i18n = $j${"ru": {"prompt": "Брусок 4,0 кг связан с бруском 2,0 кг лёгкой нитью на гладком столе, а горизонтальная сила 12 Н тянет брусок 4,0 кг. Каково натяжение нити?", "options": ["4,0 Н", "6,0 Н", "8,0 Н", "12 Н"], "explanation": "Система движется с ускорением a = 12 / 6,0 = 2,0 м/с^2. Нить разгоняет только задний брусок, поэтому T = 2,0 кг * 2,0 м/с^2 = 4,0 Н. 8,0 Н — то, что остаётся на разгон переднего бруска."}, "kk": {"prompt": "Тегіс үстелде 4,0 кг білеуше 2,0 кг білеушемен жеңіл жіппен байланған, ал 12 Н горизонталь күш 4,0 кг білеушені тартады. Керілу қандай?", "options": ["4,0 Н", "6,0 Н", "8,0 Н", "12 Н"], "explanation": "Жүйе a = 12 / 6,0 = 2,0 м/с^2 үдеумен қозғалады. Жіп тек артқы білеушені үдетуі керек, сондықтан T = 2,0 кг * 2,0 м/с^2 = 4,0 Н. 8,0 Н — алдыңғы білеушені үдетуге қалатыны."}}$j$::jsonb where id = 'mech-q3';
update public.quiz_questions set i18n = $j${"ru": {"prompt": "Цилиндр скатывается с наклонной плоскости без проскальзывания. Что делает сила трения покоя в точке касания?", "options": ["Создаёт момент, раскручивающий цилиндр, и не совершает работы", "Совершает отрицательную работу и нагревает поверхность", "Компенсирует часть силы тяжести и не совершает работы", "Ничего — для качения трение не нужно"], "explanation": "Только у этой силы есть плечо относительно центра, поэтому именно она заставляет цилиндр вращаться. Точка касания мгновенно покоится, так что сила действует без перемещения: ни работы, ни нагрева. Без неё цилиндр скользил бы, а не катился."}, "kk": {"prompt": "Цилиндр көлбеу жазықтықтан сырғанаусыз домалап түседі. Жанасу нүктесіндегі тыныштық үйкеліс күші не істейді?", "options": ["Цилиндрді айналдыратын моментті береді және жұмыс істемейді", "Теріс жұмыс істеп, бетті қыздырады", "Ауырлық күшінің бір бөлігін теңестіреді және жұмыс істемейді", "Ештеңе — домалауға үйкеліс керек емес"], "explanation": "Центрге қатысты иіні бар жалғыз күш сол, сондықтан цилиндрді айналдыратын да сол. Жанасу нүктесі лездік тыныштықта, сондықтан күш орын ауыстырусыз әсер етеді: жұмыс та, қызу да жоқ. Онсыз цилиндр домаламай, сырғанар еді."}}$j$::jsonb where id = 'mech-q4';
update public.quiz_questions set i18n = $j${"ru": {"prompt": "Для колеса радиуса R, катящегося без проскальзывания, какая пара соотношений верна?", "options": ["v = omega R и a = alpha R", "v = omega / R и a = alpha / R", "v = omega R и a = omega^2 R", "v = alpha R и a = omega R"], "explanation": "Качение связывает поступательное движение с вращением: за один оборот центр проходит одну длину окружности. Дифференцируя v = omega R, получаем a = alpha R. Сочетание omega^2 R — центростремительное ускорение точки обода, это другая величина."}, "kk": {"prompt": "Сырғанаусыз домалайтын R радиусты дөңгелек үшін қай қатынастар жұбы дұрыс?", "options": ["v = omega R және a = alpha R", "v = omega / R және a = alpha / R", "v = omega R және a = omega^2 R", "v = alpha R және a = omega R"], "explanation": "Домалау ілгерілемелі қозғалысты айналумен байланыстырады: бір айналымда центр бір шеңбер ұзындығына жылжиды. v = omega R-ді бір рет дифференциалдасақ, a = alpha R шығады. omega^2 R — шеңбер бойындағы нүктенің центрге тартқыш үдеуі, бұл басқа шама."}}$j$::jsonb where id = 'mech-q5';
update public.quiz_questions set i18n = $j${"ru": {"prompt": "Обруч и сплошной цилиндр одной массы и радиуса одновременно отпускают с одной высоты на одной наклонной плоскости, оба катятся без проскальзывания. Кто первым окажется внизу?", "options": ["Цилиндр", "Обруч", "Одновременно", "Зависит от массы"], "explanation": "Оба превращают одну и ту же потенциальную энергию, но у обруча вся масса на радиусе R, поэтому I / (m R^2) = 1 против 1/2 у цилиндра. У обруча больше энергии уходит во вращение и меньше — в движение, поэтому он медленнее. Ни масса, ни радиус в ответ не входят."}, "kk": {"prompt": "Массасы мен радиусы бірдей шеңбер (құрсау) мен тұтас цилиндр бір көлбеу жазықтықта бір биіктіктен бірге жіберіледі, екеуі де сырғанаусыз домалайды. Қайсысы төменге бірінші жетеді?", "options": ["Цилиндр", "Құрсау", "Бірге жетеді", "Массаға байланысты"], "explanation": "Екеуі де бірдей потенциалдық энергияны түрлендіреді, бірақ құрсаудың бүкіл массасы R радиуста, сондықтан I / (m R^2) = 1, ал цилиндрде 1/2. Құрсау энергиясының көбі айналуға, азы қозғалысқа кетеді, сондықтан ол баяу. Жауапқа масса да, радиус та кірмейді."}}$j$::jsonb where id = 'mech-q6';
update public.quiz_questions set i18n = $j${"ru": {"prompt": "Какой шаг составляет алгоритм Евклида?", "options": ["НОД(a,b) = НОД(b, a mod b)", "НОД(a,b) = НОД(a-b, b-a)", "НОД(a,b) = a*b / (a+b)", "Разложить оба числа и сравнить простые множители"], "explanation": "Замена большего числа остатком сохраняет НОД, потому что любой общий делитель a и b делит и a mod b. Разложение на множители в принципе работает, но гораздо медленнее, а для больших чисел безнадёжно."}, "kk": {"prompt": "Евклид алгоритмінің қадамы қайсысы?", "options": ["ЕҮОБ(a,b) = ЕҮОБ(b, a mod b)", "ЕҮОБ(a,b) = ЕҮОБ(a-b, b-a)", "ЕҮОБ(a,b) = a*b / (a+b)", "Екеуін де жіктеп, жай көбейткіштерді салыстыру"], "explanation": "Үлкен санды қалдықпен ауыстыру ЕҮОБ-ты сақтайды, өйткені a мен b-ның кез келген ортақ бөлгіші a mod b-ны да бөледі. Жіктеу негізінен жұмыс істейді, бірақ әлдеқайда баяу, ал үлкен сандар үшін үмітсіз."}}$j$::jsonb where id = 'nt-q1';
update public.quiz_questions set i18n = $j${"ru": {"prompt": "НОД(1071, 462) равен", "options": ["21", "3", "7", "147"], "explanation": "1071 = 2*462 + 147; 462 = 3*147 + 21; 147 = 7*21 + 0. Ответ — последний ненулевой остаток, 21. 147 — промежуточный остаток, а не НОД."}, "kk": {"prompt": "ЕҮОБ(1071, 462) тең", "options": ["21", "3", "7", "147"], "explanation": "1071 = 2*462 + 147; 462 = 3*147 + 21; 147 = 7*21 + 0. Жауап — соңғы нөлдік емес қалдық, 21. 147 — аралық қалдық, ЕҮОБ емес."}}$j$::jsonb where id = 'nt-q2';
update public.quiz_questions set i18n = $j${"ru": {"prompt": "Когда у a есть обратный элемент по модулю n?", "options": ["Ровно тогда, когда НОД(a,n) = 1", "Всегда, когда a простое", "Всегда, когда a < n", "Всегда"], "explanation": "Безу даёт ax + ny = 1 ровно тогда, когда НОД равен 1, а если прочитать это по модулю n, x и есть обратный. Простое a всё равно может иметь общий множитель с n: у 3 нет обратного по модулю 6."}, "kk": {"prompt": "a-ның n модулі бойынша кері элементі қашан болады?", "options": ["ЕҮОБ(a,n) = 1 болғанда ғана", "a жай сан болғанда әрдайым", "a < n болғанда әрдайым", "Әрдайым"], "explanation": "Безу ЕҮОБ 1 болғанда ғана ax + ny = 1 береді, ал мұны n модулі бойынша оқысақ, x — кері элемент. Жай a-ның да n-мен ортақ көбейткіші болуы мүмкін — 3-тің 6 модулі бойынша кері элементі жоқ."}}$j$::jsonb where id = 'nt-q3';
update public.quiz_questions set i18n = $j${"ru": {"prompt": "Какова последняя цифра числа 7^100?", "options": ["1", "7", "9", "3"], "explanation": "Степени 7 оканчиваются на 7, 9, 3, 1, а затем повторяются, так что порядок по модулю 10 равен 4. Поскольку 100 кратно 4, последняя цифра — 1. Остальные варианты — ответы для показателей, дающих 1, 2 и 3 по модулю 4."}, "kk": {"prompt": "7^100 санының соңғы цифры қандай?", "options": ["1", "7", "9", "3"], "explanation": "7-нің дәрежелері 7, 9, 3, 1-ге аяқталып, қайталанады, сондықтан 10 модулі бойынша реті 4. 100 саны 4-ке еселі болғандықтан, соңғы цифр 1. Басқа нұсқалар — 4 модулі бойынша 1, 2 және 3 беретін көрсеткіштердің жауаптары."}}$j$::jsonb where id = 'nt-q4';
update public.quiz_questions set i18n = $j${"ru": {"prompt": "Для простого p, не делящего a, малая теорема Ферма утверждает", "options": ["a^(p-1) = 1 mod p", "a^p = 1 mod p", "a^(p-1) = 0 mod p", "p^(a-1) = 1 mod a"], "explanation": "Показатель — p-1, а не p: второй вариант — неверно переписанное родственное утверждение a^p = a mod p. Это стандартный способ свернуть огромный показатель по простому модулю."}, "kk": {"prompt": "a-ны бөлмейтін жай p үшін Ферманың кіші теоремасы айтады:", "options": ["a^(p-1) = 1 mod p", "a^p = 1 mod p", "a^(p-1) = 0 mod p", "p^(a-1) = 1 mod a"], "explanation": "Көрсеткіш p емес, p-1 — екінші нұсқа a^p = a mod p туыстас тұжырымының қате түрлендірілгені. Бұл жай модуль бойынша орасан зор көрсеткішті ықшамдаудың стандарт тәсілі."}}$j$::jsonb where id = 'nt-q5';
update public.quiz_questions set i18n = $j${"ru": {"prompt": "Если НОД(a,b) = 6 и a*b = 216, чему равно НОК(a,b)?", "options": ["36", "6", "216", "1296"], "explanation": "НОД * НОК = a*b, значит НОК = 216/6 = 36. Это тождество стоит помнить именно потому, что оно переводит одно в другое без всякого разложения."}, "kk": {"prompt": "Егер ЕҮОБ(a,b) = 6 және a*b = 216 болса, ЕКОЕ(a,b) неге тең?", "options": ["36", "6", "216", "1296"], "explanation": "ЕҮОБ * ЕКОЕ = a*b, демек ЕКОЕ = 216/6 = 36. Бұл теңдікті есте сақтау керек, өйткені ол ешқандай жіктеусіз бірін екіншісіне айналдырады."}}$j$::jsonb where id = 'nt-q6';
update public.quiz_questions set i18n = $j${"ru": {"prompt": "Что означает W в записи delta U = Q - W?", "options": ["Работу, совершённую газом над окружением", "Работу, совершённую окружением над газом", "Полную энергию газа", "Теплоту, отданную холодильнику"], "explanation": "При знаке минус W — работа, которую совершает газ. Расширение стоит ему энергии, поэтому U уменьшается, если теплота не восполнит разницу. Другое соглашение, delta U = Q + W, определяет W наоборот — годится любое, если не менять его посреди задачи."}, "kk": {"prompt": "delta U = Q - W жазбасында W нені білдіреді?", "options": ["Газдың қоршаған ортаға жасаған жұмысын", "Қоршаған ортаның газға жасаған жұмысын", "Газдың толық энергиясын", "Суытқышқа берілген жылуды"], "explanation": "Минус таңбасымен W — газ жасайтын жұмыс. Ұлғаю оған энергияға түседі, сондықтан жылу айырманы толтырмаса, U азаяды. Басқа келісім, delta U = Q + W, W-ны керісінше анықтайды — есептің ортасында ауыстырмасаңыз, кез келгені жарайды."}}$j$::jsonb where id = 'thermo-q1';
update public.quiz_questions set i18n = $j${"ru": {"prompt": "Газ нагревают в закрытом жёстком сосуде. Какую работу он совершает?", "options": ["Никакой", "p delta V", "Площадь внутри процесса", "Равную подведённой теплоте"], "explanation": "Для работы нужно изменение объёма — W = интеграл p dV, а dV всё время равно нулю. На pV-диаграмме процесс — вертикальная линия, под ней нет площади. Вся теплота уходит во внутреннюю энергию."}, "kk": {"prompt": "Газ тұйық қатты ыдыста қыздырылады. Ол қанша жұмыс жасайды?", "options": ["Ешқандай", "p delta V", "Процесс шектеген аудан", "Берілген жылуға тең"], "explanation": "Жұмыс үшін көлемнің өзгеруі керек — W = p dV интегралы, ал dV әрдайым нөл. pV-диаграммада процесс — тік сызық, оның астында аудан жоқ. Бүкіл жылу ішкі энергияға кетеді."}}$j$::jsonb where id = 'thermo-q2';
update public.quiz_questions set i18n = $j${"ru": {"prompt": "На pV-диаграмме полезная работа газа за полный цикл равна", "options": ["площади внутри цикла", "площади только под верхней ветвью", "нулю, потому что газ возвращается в исходное состояние", "всей полученной теплоте"], "explanation": "Газ возвращается в то же состояние, поэтому за цикл delta U = 0 — но это значит, что суммарная теплота равна полезной работе, а не нулю. Работа, совершённая на верхней ветви, и работа, затраченная на нижней, отличаются ровно на площадь внутри цикла."}, "kk": {"prompt": "pV-диаграммада газдың бір толық циклдегі пайдалы жұмысы тең", "options": ["цикл шектеген ауданға", "тек жоғарғы тармақ астындағы ауданға", "нөлге, өйткені газ бастапқы күйге оралады", "барлық алынған жылуға"], "explanation": "Газ сол күйге оралады, сондықтан цикл бойы delta U = 0 — бірақ бұл жиынтық жылу нөлге емес, пайдалы жұмысқа тең дегенді білдіреді. Жоғарғы тармақтағы шыққан жұмыс пен төменгі тармақтағы жұмсалған жұмыс дәл цикл ішіндегі ауданға ерекшеленеді."}}$j$::jsonb where id = 'thermo-q3';
update public.quiz_questions set i18n = $j${"ru": {"prompt": "Идеальный газ расширяется изотермически. Какое утверждение верно?", "options": ["delta U = 0, поэтому полученная теплота равна совершённой работе", "Q = 0, поэтому газ остывает", "W = 0, так как температура не меняется", "delta U равно работе газа"], "explanation": "У идеального газа внутренняя энергия зависит только от температуры, поэтому в изотермическом процессе delta U = 0 и первое начало сводится к Q = W. Теплота поступает ровно с той скоростью, с какой газ тратит её на расширение. Q = 0 было бы адиабатным процессом — это другой процесс."}, "kk": {"prompt": "Идеал газ изотермиялық ұлғаяды. Қай тұжырым дұрыс?", "options": ["delta U = 0, сондықтан алынған жылу жасалған жұмысқа тең", "Q = 0, сондықтан газ суиды", "W = 0, өйткені температура өзгермейді", "delta U газдың жұмысына тең"], "explanation": "Идеал газдың ішкі энергиясы тек температураға тәуелді, сондықтан изотермиялық процесте delta U = 0 және бірінші заң Q = W-ға келеді. Жылу газ оны ұлғаюға жұмсайтын жылдамдықпен дәл кіреді. Q = 0 адиабаталық, басқа процесс болар еді."}}$j$::jsonb where id = 'thermo-q4';
update public.quiz_questions set i18n = $j${"ru": {"prompt": "КПД цикла определяется как", "options": ["полезная работа, делённая на полученную теплоту", "полезная работа, делённая на суммарную теплоту", "полученная теплота, делённая на отданную", "полезная работа, делённая на внутреннюю энергию"], "explanation": "КПД — это то, что получили, делённое на то, за что заплатили, а платим мы за теплоту, которая поступает. Если в знаменатель поставить суммарную теплоту, он совпадёт с числителем и даст 100% для любого цикла — верный признак, что определение съехало."}, "kk": {"prompt": "Циклдің ПӘК-і былай анықталады:", "options": ["пайдалы жұмыс алынған жылуға бөлінген", "пайдалы жұмыс жиынтық жылуға бөлінген", "алынған жылу берілген жылуға бөлінген", "пайдалы жұмыс ішкі энергияға бөлінген"], "explanation": "ПӘК — алғаныңыз төлегеніңізге бөлінгені, ал біз кіретін жылу үшін төлейміз. Бөлімге жиынтық жылуды қойсаңыз, ол алыммен бірдей болып, кез келген цикл үшін 100% береді — анықтаманың тайғанағанының айқын белгісі."}}$j$::jsonb where id = 'thermo-q5';
update public.quiz_questions set i18n = $j${"ru": {"prompt": "Цикл на pV-диаграмме обходится против часовой стрелки. Что это?", "options": ["Холодильник: работа затрачивается, теплота переносится", "Двигатель с необычно высоким КПД", "Невозможный цикл", "Двигатель на задней передаче, который всё ещё производит работу"], "explanation": "Против часовой стрелки — значит сжатие происходит при большем давлении, поэтому работы затрачивается больше, чем получается. Полезная работа отрицательна, и машина тратит её на перенос теплоты от холодного к горячему — это холодильник или тепловой насос."}, "kk": {"prompt": "pV-диаграммада цикл сағат тіліне қарсы жүреді. Бұл не?", "options": ["Тоңазытқыш: жұмыс жұмсалады, жылу тасымалданады", "ПӘК-і ерекше жоғары қозғалтқыш", "Мүмкін емес цикл", "Кері берілістегі, бірақ әлі де жұмыс өндіретін қозғалтқыш"], "explanation": "Сағат тіліне қарсы — сығу жоғарырақ қысымда жүреді, сондықтан шыққаннан көп жұмыс жұмсалады. Пайдалы жұмыс теріс, және машина оны жылуды суықтан ыстыққа тасымалдауға жұмсайды — тоңазытқыш немесе жылу сорғысы."}}$j$::jsonb where id = 'thermo-q6';

update public.flashcards set i18n = $j${"ru": {"front": "Деление с остатком", "back": "a = qn + r, 0 <= r < n, единственным образом. Это r и есть «a mod n»."}, "kk": {"front": "Қалдықпен бөлу", "back": "a = qn + r, 0 <= r < n, жалғыз тәсілмен. Сол r — «a mod n»."}}$j$::jsonb where user_id is null and front = 'Division with remainder';
update public.flashcards set i18n = $j${"ru": {"front": "Шаг алгоритма Евклида", "back": "НОД(a,b) = НОД(b, a mod b); остановиться, когда остаток станет нулём."}, "kk": {"front": "Евклид алгоритмінің қадамы", "back": "ЕҮОБ(a,b) = ЕҮОБ(b, a mod b); қалдық нөл болғанда тоқтау."}}$j$::jsonb where user_id is null and front = 'The Euclidean algorithm step';
update public.flashcards set i18n = $j${"ru": {"front": "Как связаны НОД и НОК", "back": "НОД(a,b) * НОК(a,b) = a*b."}, "kk": {"front": "ЕҮОБ пен ЕКОЕ байланысы", "back": "ЕҮОБ(a,b) * ЕКОЕ(a,b) = a*b."}}$j$::jsonb where user_id is null and front = 'gcd and lcm, related';
update public.flashcards set i18n = $j${"ru": {"front": "Соотношение Безу", "back": "НОД(a,b) = ax + by для некоторых целых x и y."}, "kk": {"front": "Безу теңдігі", "back": "Кейбір бүтін x және y үшін ЕҮОБ(a,b) = ax + by."}}$j$::jsonb where user_id is null and front = 'Bezout''s identity';
update public.flashcards set i18n = $j${"ru": {"front": "Когда a обратимо по модулю n?", "back": "Ровно тогда, когда НОД(a,n) = 1."}, "kk": {"front": "a n модулі бойынша қашан кері айналады?", "back": "ЕҮОБ(a,n) = 1 болғанда ғана."}}$j$::jsonb where user_id is null and front = 'When is a invertible mod n?';
update public.flashcards set i18n = $j${"ru": {"front": "Порядок a по модулю n", "back": "Наименьшее k, при котором a^k = 1 mod n. Тогда показатели можно уменьшать по модулю k."}, "kk": {"front": "a-ның n модулі бойынша реті", "back": "a^k = 1 mod n болатын ең кіші k. Сонда көрсеткіштерді k модулі бойынша азайтуға болады."}}$j$::jsonb where user_id is null and front = 'The order of a modulo n';
update public.flashcards set i18n = $j${"ru": {"front": "Малая теорема Ферма", "back": "Для простого p, не делящего a: a^(p-1) = 1 mod p."}, "kk": {"front": "Ферманың кіші теоремасы", "back": "a-ны бөлмейтін жай p үшін: a^(p-1) = 1 mod p."}}$j$::jsonb where user_id is null and front = 'Fermat''s little theorem';
update public.flashcards set i18n = $j${"ru": {"front": "Теорема Эйлера", "back": "a^phi(n) = 1 mod n, если НОД(a,n) = 1."}, "kk": {"front": "Эйлер теоремасы", "back": "ЕҮОБ(a,n) = 1 болса, a^phi(n) = 1 mod n."}}$j$::jsonb where user_id is null and front = 'Euler''s theorem';
update public.flashcards set i18n = $j${"ru": {"front": "Какая операция в сравнениях опасна?", "back": "Сокращение. Множитель должен быть обратим по модулю n."}, "kk": {"front": "Салыстыруларда қай амал қауіпті?", "back": "Қысқарту. Көбейткіш n модулі бойынша кері айналатын болуы керек."}}$j$::jsonb where user_id is null and front = 'Which operation is unsafe in a congruence?';
update public.flashcards set i18n = $j${"ru": {"front": "Что нерастяжимая нить задаёт для связанных тел?", "back": "Связь между их ускорениями — из постоянства длины. Прямо по столу или через неподвижный блок: один общий модуль ускорения. С подвижным блоком груз проходит вдвое меньше свободного конца."}, "kk": {"front": "Созылмайтын жіп байланыстырған денелер арасында нені белгілейді?", "back": "Тұрақты ұзындықтан шығатын үдеулер арасындағы байланысты. Үстел бойымен тура немесе қозғалмайтын блок арқылы: бір ортақ үдеу модулі. Жылжымалы блокпен жүк бос ұшынан екі есе аз жол жүреді."}}$j$::jsonb where user_id is null and front = 'What does an inextensible string fix between the bodies it connects?';
update public.flashcards set i18n = $j${"ru": {"front": "Как исключить натяжение в задаче о связанных телах?", "back": "Сложить уравнения для каждого тела. Натяжение — внутренняя сила, оно входит по разу с каждым знаком и сокращается."}, "kk": {"front": "Байланысқан денелер есебінде керілуді қалай жоюға болады?", "back": "Әр дененің теңдеулерін қосу. Керілу — ішкі күш, ол әр таңбамен бір реттен кіріп, қысқарады."}}$j$::jsonb where user_id is null and front = 'How do you eliminate the tension in a connected-body problem?';
update public.flashcards set i18n = $j${"ru": {"front": "Общее ускорение найдено. Как получить натяжение?", "back": "Подставить его в уравнение для одного тела. Уравнение для системы не может дать внутреннюю силу."}, "kk": {"front": "Ортақ үдеу табылды. Керілуді қалай алуға болады?", "back": "Оны бір дененің теңдеуіне қою. Жүйенің теңдеуі ішкі күшті бере алмайды."}}$j$::jsonb where user_id is null and front = 'Having found the shared acceleration, how do you get the tension?';
update public.flashcards set i18n = $j${"ru": {"front": "Качение без проскальзывания — две кинематические связи", "back": "v = omega R и a = alpha R."}, "kk": {"front": "Сырғанаусыз домалау — екі кинематикалық байланыс", "back": "v = omega R және a = alpha R."}}$j$::jsonb where user_id is null and front = 'Rolling without slipping — the two kinematic links';
update public.flashcards set i18n = $j${"ru": {"front": "Совершает ли трение покоя работу над телом, катящимся без проскальзывания?", "back": "Нет. Точка касания мгновенно покоится, поэтому сила действует без перемещения."}, "kk": {"front": "Тыныштық үйкеліс сырғанаусыз домалайтын денеге жұмыс жасай ма?", "back": "Жоқ. Жанасу нүктесі лездік тыныштықта, сондықтан күш орын ауыстырусыз әсер етеді."}}$j$::jsonb where user_id is null and front = 'Does static friction do work on a body that rolls without slipping?';
update public.flashcards set i18n = $j${"ru": {"front": "Кинетическая энергия катящегося тела", "back": "(1/2) m v^2 + (1/2) I omega^2, где omega = v / R."}, "kk": {"front": "Домалайтын дененің кинетикалық энергиясы", "back": "(1/2) m v^2 + (1/2) I omega^2, мұнда omega = v / R."}}$j$::jsonb where user_id is null and front = 'Kinetic energy of a rolling body';
update public.flashcards set i18n = $j${"ru": {"front": "Момент инерции относительно оси: сплошной цилиндр, сплошной шар, обруч", "back": "(1/2) m R^2, (2/5) m R^2, m R^2."}, "kk": {"front": "Оське қатысты инерция моменті: тұтас цилиндр, тұтас шар, құрсау", "back": "(1/2) m R^2, (2/5) m R^2, m R^2."}}$j$::jsonb where user_id is null and front = 'Moment of inertia about the axis: solid cylinder, solid sphere, hoop';
update public.flashcards set i18n = $j${"ru": {"front": "Почему обруч скатывается с наклонной медленнее цилиндра?", "back": "Его масса сосредоточена на ободе, поэтому бо́льшая доля той же энергии уходит во вращение, а не в поступательное движение."}, "kk": {"front": "Құрсау көлбеу жазықтықтан цилиндрге қарағанда неге баяу домалайды?", "back": "Оның массасы шетте шоғырланған, сондықтан сол энергияның үлкен үлесі ілгерілемелі қозғалысқа емес, айналуға кетеді."}}$j$::jsonb where user_id is null and front = 'Why does a hoop roll down an incline more slowly than a cylinder?';
update public.flashcards set i18n = $j${"ru": {"front": "Когда количества умножают, а когда складывают?", "back": "Умножают для независимых этапов одного выбора; складывают для взаимоисключающих случаев."}, "kk": {"front": "Сандарды қашан көбейтеді, қашан қосады?", "back": "Бір таңдаудың тәуелсіз кезеңдерін көбейтеді; бір-бірін жоққа шығаратын жағдайларды қосады."}}$j$::jsonb where user_id is null and front = 'When do you multiply counts, and when do you add?';
update public.flashcards set i18n = $j${"ru": {"front": "Размещение и сочетание", "back": "P(n,k) = n!/(n-k)! считает расстановки; C(n,k) = n!/(k!(n-k)!) считает выборы."}, "kk": {"front": "Орналастыру мен теру", "back": "P(n,k) = n!/(n-k)! орналастыруларды санайды; C(n,k) = n!/(k!(n-k)!) таңдауларды санайды."}}$j$::jsonb where user_id is null and front = 'Permutation against combination';
update public.flashcards set i18n = $j${"ru": {"front": "Почему для C(n,k) делят на k!?", "back": "Каждый выбор был посчитан по разу для каждого из k! порядков, в которых его можно записать."}, "kk": {"front": "C(n,k) алу үшін неге k!-ға бөледі?", "back": "Әр таңдау оны жазудың k! ретінің әрқайсысы үшін бір рет саналған."}}$j$::jsonb where user_id is null and front = 'Why divide by k! to get C(n,k)?';
update public.flashcards set i18n = $j${"ru": {"front": "C(n,k) = ?", "back": "C(n,n-k). Выбрать, что взять, — значит выбрать, что оставить."}, "kk": {"front": "C(n,k) = ?", "back": "C(n,n-k). Нені алуды таңдау — нені қалдыруды таңдау."}}$j$::jsonb where user_id is null and front = 'C(n,k) = ?';
update public.flashcards set i18n = $j${"ru": {"front": "Сумма строки биномиальных коэффициентов", "back": "C(n,0)+...+C(n,n) = 2^n — все подмножества, посчитанные по размеру."}, "kk": {"front": "Биномдық коэффициенттер жолының қосындысы", "back": "C(n,0)+...+C(n,n) = 2^n — өлшемі бойынша саналған барлық ішкі жиындар."}}$j$::jsonb where user_id is null and front = 'The sum of a row of binomial coefficients';
update public.flashcards set i18n = $j${"ru": {"front": "Самый быстрый путь к «хотя бы одному»", "back": "Все минус ни одного."}, "kk": {"front": "«Кемінде біреуге» ең жылдам жол", "back": "Барлығы минус біреуі де жоқ."}}$j$::jsonb where user_id is null and front = 'The quickest route to "at least one"';
update public.flashcards set i18n = $j${"ru": {"front": "Включения-исключения для двух множеств", "back": "|A или B| = |A| + |B| - |A и B|."}, "kk": {"front": "Екі жиын үшін қосу-шегеру", "back": "|A немесе B| = |A| + |B| - |A және B|."}}$j$::jsonb where user_id is null and front = 'Inclusion-exclusion for two sets';
update public.flashcards set i18n = $j${"ru": {"front": "Принцип Дирихле", "back": "n+1 предмет в n ящиках — в каком-то ящике два. Он обещает существование, но не говорит, какой ящик."}, "kk": {"front": "Дирихле принципі", "back": "n жәшікте n+1 зат болса, бір жәшікте екеуі бар. Ол бар екенін уәде етеді, қай жәшік екенін емес."}}$j$::jsonb where user_id is null and front = 'Pigeonhole principle';
update public.flashcards set i18n = $j${"ru": {"front": "Шары и перегородки", "back": "k одинаковых предметов по n различным ящикам: C(k+n-1, n-1)."}, "kk": {"front": "Шарлар мен бөгеттер", "back": "k бірдей затты n таңбаланған жәшікке: C(k+n-1, n-1)."}}$j$::jsonb where user_id is null and front = 'Stars and bars';
update public.flashcards set i18n = $j${"ru": {"front": "Сформулируйте первое начало и объясните каждый символ", "back": "delta U = Q - W. Q — теплота, подведённая к газу, W — работа газа, delta U — изменение внутренней энергии."}, "kk": {"front": "Бірінші заңды тұжырымдап, әр белгіні түсіндіріңіз", "back": "delta U = Q - W. Q — газға берілген жылу, W — газдың жұмысы, delta U — ішкі энергияның өзгерісі."}}$j$::jsonb where user_id is null and front = 'State the first law, and say what each symbol means';
update public.flashcards set i18n = $j${"ru": {"front": "Как найти работу по pV-диаграмме?", "back": "Это площадь под графиком процесса. Для замкнутого цикла полезная работа — площадь внутри цикла."}, "kk": {"front": "Жұмысты pV-диаграммадан қалай оқиды?", "back": "Бұл процесс сызығы астындағы аудан. Тұйық цикл үшін пайдалы жұмыс — цикл шектеген аудан."}}$j$::jsonb where user_id is null and front = 'How do you read the work off a pV diagram?';
update public.flashcards set i18n = $j${"ru": {"front": "Работа в изохорном процессе", "back": "Ноль — объём не меняется, под линией нет площади."}, "kk": {"front": "Изохоралық процестегі жұмыс", "back": "Нөл — көлем өзгермейді, сызық астында аудан жоқ."}}$j$::jsonb where user_id is null and front = 'Work done in an isochoric process';
update public.flashcards set i18n = $j${"ru": {"front": "Изотермическое расширение идеального газа", "back": "delta U = 0, значит Q = W: вся теплота сразу уходит в работу."}, "kk": {"front": "Идеал газдың изотермиялық ұлғаюы", "back": "delta U = 0, демек Q = W: бүкіл жылу бірден жұмыс болып шығады."}}$j$::jsonb where user_id is null and front = 'Isothermal expansion of an ideal gas';
update public.flashcards set i18n = $j${"ru": {"front": "Адиабатный процесс", "back": "Q = 0, значит delta U = -W. Расширяясь, газ остывает, потому что тратит собственную внутреннюю энергию."}, "kk": {"front": "Адиабаталық процесс", "back": "Q = 0, демек delta U = -W. Ұлғайған газ өз ішкі энергиясын жұмсағандықтан суиды."}}$j$::jsonb where user_id is null and front = 'Adiabatic process';
update public.flashcards set i18n = $j${"ru": {"front": "Внутренняя энергия идеального газа", "back": "Зависит только от температуры: delta U = n Cv delta T в любом процессе, а не только при постоянном объёме."}, "kk": {"front": "Идеал газдың ішкі энергиясы", "back": "Тек температураның функциясы: delta U = n Cv delta T кез келген процесте, тек тұрақты көлемде ғана емес."}}$j$::jsonb where user_id is null and front = 'Internal energy of an ideal gas';
update public.flashcards set i18n = $j${"ru": {"front": "КПД цикла", "back": "eta = W_полезн / Q_получ, где Q_получ — сумма только по участкам, на которых газ получает теплоту."}, "kk": {"front": "Циклдің ПӘК-і", "back": "eta = W_пайд / Q_алын, мұнда Q_алын тек газға жылу кіретін бөліктерді қосады."}}$j$::jsonb where user_id is null and front = 'Efficiency of a cycle';
update public.flashcards set i18n = $j${"ru": {"front": "По часовой и против часовой стрелки на pV-диаграмме", "back": "По часовой: работа на выходе, двигатель. Против часовой: работа на входе, холодильник."}, "kk": {"front": "pV-диаграммада сағат тілімен және оған қарсы", "back": "Сағат тілімен: жұмыс шығады, қозғалтқыш. Сағат тіліне қарсы: жұмыс кіреді, тоңазытқыш."}}$j$::jsonb where user_id is null and front = 'Clockwise against anticlockwise on a pV diagram';
update public.flashcards set i18n = $j${"ru": {"front": "Предел КПД между двумя температурами", "back": "КПД Карно 1 - Tх/Tн, обе температуры в кельвинах."}, "kk": {"front": "Екі температура арасындағы ПӘК шегі", "back": "Карно мәні 1 - Tс/Tқ, екі температура да кельвинмен."}}$j$::jsonb where user_id is null and front = 'The ceiling on efficiency between two temperatures';
update public.flashcards set i18n = $j${"ru": {"front": "Виет для квадратного ax^2+bx+c", "back": "Сумма корней = -b/a, произведение = c/a."}, "kk": {"front": "ax^2+bx+c квадрат теңдеуі үшін Виет", "back": "Түбірлер қосындысы = -b/a, көбейтіндісі = c/a."}}$j$::jsonb where user_id is null and front = 'Vieta for a quadratic ax^2+bx+c';
update public.flashcards set i18n = $j${"ru": {"front": "Виет для кубического ax^3+bx^2+cx+d", "back": "Сумма = -b/a, сумма попарных произведений = c/a, произведение = -d/a."}, "kk": {"front": "ax^3+bx^2+cx+d кубтық теңдеуі үшін Виет", "back": "Қосынды = -b/a, жұп көбейтінділер қосындысы = c/a, көбейтінді = -d/a."}}$j$::jsonb where user_id is null and front = 'Vieta for a cubic ax^3+bx^2+cx+d';
update public.flashcards set i18n = $j${"ru": {"front": "Перепишите r^2 + s^2 через Виета", "back": "(r+s)^2 - 2rs."}, "kk": {"front": "r^2 + s^2-ты Виет арқылы қайта жазыңыз", "back": "(r+s)^2 - 2rs."}}$j$::jsonb where user_id is null and front = 'Rewrite r^2 + s^2 using Vieta';
update public.flashcards set i18n = $j${"ru": {"front": "Перепишите 1/r + 1/s", "back": "(r+s)/(rs)."}, "kk": {"front": "1/r + 1/s-ты қайта жазыңыз", "back": "(r+s)/(rs)."}}$j$::jsonb where user_id is null and front = 'Rewrite 1/r + 1/s';
update public.flashcards set i18n = $j${"ru": {"front": "Квадратное уравнение по сумме S и произведению P", "back": "x^2 - Sx + P = 0."}, "kk": {"front": "S қосындысы мен P көбейтіндісінен квадрат теңдеу құру", "back": "x^2 - Sx + P = 0."}}$j$::jsonb where user_id is null and front = 'Build a quadratic from a sum S and product P';
update public.flashcards set i18n = $j${"ru": {"front": "Теорема Безу (об остатке)", "back": "При делении p(x) на (x-k) остаток равен p(k)."}, "kk": {"front": "Безу теоремасы (қалдық туралы)", "back": "p(x)-ті (x-k)-ға бөлгенде p(k) қалады."}}$j$::jsonb where user_id is null and front = 'Remainder theorem';
update public.flashcards set i18n = $j${"ru": {"front": "Теорема о множителе", "back": "(x-k) делит p(x) ровно тогда, когда p(k) = 0."}, "kk": {"front": "Көбейткіш туралы теорема", "back": "(x-k) p(x)-ті p(k) = 0 болғанда ғана бөледі."}}$j$::jsonb where user_id is null and front = 'Factor theorem';
update public.flashcards set i18n = $j${"ru": {"front": "Теорема о рациональных корнях", "back": "Для несократимой дроби p/q: p делит свободный член, q делит старший коэффициент."}, "kk": {"front": "Рационал түбірлер туралы теорема", "back": "Қысқартылмайтын p/q үшін: p бос мүшені, q жоғарғы коэффициентті бөледі."}}$j$::jsonb where user_id is null and front = 'Rational root theorem';
update public.flashcards set i18n = $j${"ru": {"front": "Что говорит дискриминант", "back": "Положителен: два различных действительных корня. Ноль: один кратный. Отрицателен: пара комплексно сопряжённых."}, "kk": {"front": "Дискриминант не айтады", "back": "Оң: екі әртүрлі нақты түбір. Нөл: бір еселі. Теріс: түйіндес комплекс жұп."}}$j$::jsonb where user_id is null and front = 'What the discriminant tells you';
update public.flashcards set i18n = $j${"ru": {"front": "Сопротивление однородного проводника", "back": "R = rho L / A — удельное сопротивление, умноженное на длину и делённое на площадь сечения."}, "kk": {"front": "Біртекті өткізгіштің кедергісі", "back": "R = rho L / A — меншікті кедергі көбейтілген ұзындық, бөлінген қима ауданы."}}$j$::jsonb where user_id is null and front = 'Resistance of a uniform conductor';
update public.flashcards set i18n = $j${"ru": {"front": "От чего зависит удельное сопротивление?", "back": "От материала и его температуры. Не от формы и не от тока."}, "kk": {"front": "Меншікті кедергі неге тәуелді?", "back": "Материал мен оның температурасына. Пішінге де, токқа да емес."}}$j$::jsonb where user_id is null and front = 'What does resistivity depend on?';
update public.flashcards set i18n = $j${"ru": {"front": "Диаметр провода удвоили. Что с R?", "back": "Уменьшилось в четыре раза: площадь пропорциональна квадрату диаметра."}, "kk": {"front": "Сымның диаметрін екі еселеді. R не болады?", "back": "Төрт есе азаяды: аудан диаметрдің квадратына пропорционал."}}$j$::jsonb where user_id is null and front = 'Double the diameter of a wire. What happens to R?';
update public.flashcards set i18n = $j${"ru": {"front": "Провод растянули в n раз при постоянном объёме. Что с R?", "back": "Умножилось на n^2 — провод стал одновременно длиннее и тоньше."}, "kk": {"front": "Сымды тұрақты көлемде n есе созды. R не болады?", "back": "n^2-ге көбейеді — бір мезгілде ұзарып та, жіңішкеріп те кетеді."}}$j$::jsonb where user_id is null and front = 'Stretch a wire to n times its length at constant volume. What happens to R?';
update public.flashcards set i18n = $j${"ru": {"front": "Последовательно и параллельно — по одной строке", "back": "Последовательно: сопротивления складываются. Параллельно: складываются обратные величины."}, "kk": {"front": "Тізбектей және параллель — бір жолдан", "back": "Тізбектей: кедергілер қосылады. Параллель: кері шамалар қосылады."}}$j$::jsonb where user_id is null and front = 'Series and parallel, in one line each';
update public.flashcards set i18n = $j${"ru": {"front": "Два резистора параллельно", "back": "R = R1 R2 / (R1 + R2). Результат всегда меньше меньшего из двух."}, "kk": {"front": "Параллель екі резистор", "back": "R = R1 R2 / (R1 + R2). Нәтиже әрдайым екеуінің кішісінен кіші."}}$j$::jsonb where user_id is null and front = 'Two resistors in parallel';
update public.flashcards set i18n = $j${"ru": {"front": "Три формы электрической мощности", "back": "P = V I = I^2 R = V^2 / R."}, "kk": {"front": "Электр қуатының үш түрі", "back": "P = V I = I^2 R = V^2 / R."}}$j$::jsonb where user_id is null and front = 'Three forms of electrical power';
update public.flashcards set i18n = $j${"ru": {"front": "Металл и полупроводник при росте температуры", "back": "У металла удельное сопротивление растёт, у полупроводника — падает."}, "kk": {"front": "Температура өскенде металл мен жартылай өткізгіш", "back": "Металдың меншікті кедергісі өседі; жартылай өткізгіштікі азаяды."}}$j$::jsonb where user_id is null and front = 'Metal against semiconductor, as temperature rises';
